insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('sat-siidlung', 'SAT-Siidlung', '', '', '', '', 'SAT-Siedlung', '[{"kategorie": "allg.", "text": "\"Siedlungsanlage im 13. Wiener Gemeindebezirk ([[Hietzing]]), am Rande des [[Hörndlwaldes]] (volle Bezeichnung: \"Siedlungsanlage der Siedlungsgenossenschaft Arbeiter und Techniker)\""}, {"kategorie": "", "text": "Sie wurde in den 1920er Jahren, nach dem [[Ersten]] Weltkrieg, im Rahmen der Wiener Siedlerbewegung errichtet. Diese Bewegung entstand als Reaktion auf die extreme Wohnungsnot und die Nahrungsmittelknappheit, die viele Menschen dazu trieb, sich in Stadtrandgebieten selbst Parzellen zu erschließen und zu bebauen"}, {"kategorie": "", "text": "Die SAT-Siedlung war eine dieser Kleinsiedlungen, die als Gartenstadt-ähnliche Wohnform mit kleinen Einfamilienhäusern und großen Gartenflächen konzipiert war. Diese Siedlungen wurden oft mit Hilfe von Genossenschaften organisiert, die den Arbeitern und kleinen Angestellten halfen, sich selbst ein Haus und eine Existenzgrundlage zu schaffen. Die Bewohner konnten dort Obst und Gemüse anbauen, um sich teilweise selbst zu versorgen"}, {"kategorie": "", "text": "Die SAT-Siedlung war Teil der größeren Entwicklung von Siedlungsgebieten in der Umgebung des Hörndlwaldes und anderer Teile von Hietzing, die durch Abholzungen des Lainzer Tiergartens möglich wurden"}, {"kategorie": "", "text": "Heute ist die Siedlung ein ruhiges Wohngebiet, das vor allem durch seine grüne Umgebung und die Nähe zum Hörndlwald geschätzt wird."}]'::jsonb, ''),
  ('siidlung-lockawiisn', 'Siidlung Lockawiisn', '', '', '', '', 'Siedlung Lockerwiese', '[{"kategorie": "allg.", "text": "\"Wohnsiedlung im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Sie erstreckt sich über mehrere Straßenzüge, darunter die [[Camillianergasse]] (1–35, 2–40), [[Wolkersbergenstraße]] (54–170), [[Engelhartgasse]] (5–47) sowie die [[Versorgungsheimstraße]] (6–50, 56–68)"}, {"kategorie": "", "text": "Diese städtische Siedlungsanlage wurde in mehreren Etappen zwischen 1928 und 1932 sowie 1938 nach Plänen des Architekten Karl Schartelmüller erbaut. die in den 1920er Jahren als Teil der Kleinsiedlungsbewegung errichtet wurde. Diese Bewegung hatte das Ziel, erschwinglichen Wohnraum für die arbeitende Bevölkerung in Form von Kleinsiedlungen zu schaffen, die auch Platz für Selbstversorgung durch Gärten boten"}, {"kategorie": "", "text": "Die Siedlung befindet sich auf einer Fläche, die ursprünglich zur Lockerwiese gehörte, einer Grünfläche, die nach der alteingesessenen Familie Locker benannt wurde"}, {"kategorie": "", "text": "Die Siedlung Lockerwiese wurde in zwei Bauphasen errichtet. Der erste Bauabschnitt erfolgte zwischen 1928 und 1932 und umfasste die meisten der Reihenhäuser. Nach einer Unterbrechung, die auf die politischen und wirtschaftlichen Umstände der Zwischenkriegszeit zurückzuführen ist, wurde die Siedlung im Jahr 1938 fertiggestellt. Die Errichtung dieser Siedlung fällt in eine Phase des intensiven städtischen Wohnbaus in Wien, der durch die Sozialpolitik der sogenannten [[Roten Wien]] geprägt war"}, {"kategorie": "", "text": "Heute ist die Siedlung Lockerwiese eine ruhige Wohngegend in [[Hietzing]], einem der grünsten und gehobensten Bezirke Wiens. Die Siedlung Lockerwiese ist ein bedeutendes Beispiel für den städtischen Wohnbau der Zwischenkriegszeit in Wien. Sie vereint das Konzept der Gartenstadt mit den Prinzipien des romantischen Sozialrealismus und zeigt, wie städtischer Wohnraum und grüne Freiflächen auf harmonische Weise kombiniert werden können."}]'::jsonb, ''),
  ('lainza-schdrossn', 'Lainza Schdrossn', '', '', '', '', 'Lainzer Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), welche die Stadtteile [[Lainz]], [[Speising]] und [[Unter-Sankt-Veit]] miteinander verbindet"}, {"kategorie": "", "text": "Sie hat eine lange Geschichte und verläuft von Hietzing aus in südwestlicher Richtung durch den Bezirk. Die Lainzer Straße ist eine der Hauptverkehrsadern in diesem Teil von Wien und führt in Richtung des Naherholungsgebiets [[Lainzer]] Tiergartens"}, {"kategorie": "", "text": "Die Straße war Teil einer historischen Römerstraße und ist nach dem Stadtteil Lainz benannt, der seit dem Mittelalter existiert und ursprünglich ein kleines Dorf außerhalb Wiens war. Lainz ist heute vor allem für den Lainzer Tiergarten bekannt, ein großes Naturschutzgebiet und ehemaliges Jagdgebiet der Habsburger. Die Lainzer Straße war historisch eine wichtige Verbindung von der Stadt Wien zu diesem Jagdgebiet und später zu den Erholungsgebieten"}, {"kategorie": "", "text": "Heute ist die Lainzer Straße eine gemischte Straße, die sowohl Wohn- als auch Geschäftsgebiete durchquert. Entlang der Straße finden sich zahlreiche Wohnhäuser, Geschäfte, Cafés und Restaurants. Die Bebauung spiegelt die gehobene und grüne Atmosphäre des Bezirks Hietzing wider, der für seine Villengegenden und Parks bekannt ist."}]'::jsonb, ''),
  ('poetzleinsduafa-friidhof', 'Pötzleinsduafa Friidhof', '', '', '', '', 'Pötzleinsdorfer Friedhof', '[{"kategorie": "", "text": "Er umfasst eine Fläche von 5.544 Quadratmetern und bietet Platz für rund 700 Grabstellen. Dieser kleine, ruhige Friedhof ist von historischem Interesse und steht im Zusammenhang mit der Geschichte des Ortes Pötzleinsdorf, der seit 1892 Teil Wiens ist"}, {"kategorie": "", "text": "Der Friedhof wurde im 18. Jahrhundert angelegt und 1823 beträchtlich erweitert, als Johann Heinrich Freiherr von Geymüller, ein prominenter Wiener Bankier, eine Familiengruft auf dem Friedhof errichten durfte. Als Gegenleistung stellte er Grundstücke zur Verfügung, um den Friedhof zu vergrößern"}, {"kategorie": "", "text": "Weitere Erweiterungen fanden 1865, nach der Eingemeindung Pötzleinsdorfs 1905, sowie 1918 statt. Im Jahr 1919 wurde ein schmiedeeisernes Gedenkkreuz für die im [[Ersten]] Weltkrieg gefallenen Pötzleinsdorfer aufgestellt"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg gehörte der Pötzleinsdorfer Friedhof zu den sogenannten Sperrfriedhöfen, die geschlossen werden sollten. Nach einer Volksbefragung beschloss der Wiener Gemeinderat jedoch am 26. September 1980, die Sperre aufzuheben. In den Jahren 1982/1983 errichtete der Architekt Erich Boltenstern eine neue Aufbahrungshalle, um den Friedhof weiterhin modern nutzen zu können."}]'::jsonb, ''),
  ('siimhiatna-friidhof', 'Siimhiatna Friidhof', '', '', '', '', 'Siebenhirtener Friedhof', '[{"kategorie": "", "text": "Er wurde 1783 angelegt und umfasst heute eine Fläche von 8.933 Quadratmetern mit rund 760 Grabstellen. Der Friedhof liegt nahe der ehemaligen Siebenhirtener Kirche, die am Petersbach stand und 1944 während eines Fliegerangriffs im Zweiten Weltkrieg zerstört wurde"}, {"kategorie": "", "text": "Nach dem Krieg wurde der Siebenhirtener Friedhof 1952 erweitert, sodass ab 1953 wieder neue Gräber vergeben werden konnten. In den Jahren 1963-1964 wurde die Aufbahrungshalle renoviert"}, {"kategorie": "", "text": "1975 gehörte der Siebenhirtener Friedhof zu jenen Friedhöfen, die als sogenannte Sperrfriedhöfe deklariert wurden, was bedeutet hätte, dass keine weiteren Bestattungen mehr stattfinden dürften. Nach einer Volksbefragung im Jahr 1980 wurde dieser Beschluss jedoch aufgehoben, und der Friedhof blieb weiterhin in Nutzung"}, {"kategorie": "", "text": "Mit seiner Gründung im späten 18. Jahrhundert, der mehrfachen Erweiterung und der Erneuerung nach dem [[Zweiten]] Weltkrieg ist er heute ein wichtiger Teil der lokalen Geschichte und bietet eine Verbindung zwischen der Vergangenheit und Gegenwart des Stadtteils [[Siebenhirten]]."}]'::jsonb, ''),
  ('rodauna-friidhof', 'Rodauna Friidhof', '', '', '', '', 'Rodauner Friedhof', '[{"kategorie": "", "text": "Er hat eine Fläche von 12.145 Quadratmetern und bietet Platz für rund 1.400 Grabstellen. Eine Besonderheit dieses Friedhofs sind die sowjetischen Kriegsgräber, die an die im Zweiten Weltkrieg gefallenen Soldaten erinnern"}, {"kategorie": "", "text": "Der heutige Rodauner Friedhof wurde 1799 am östlichen Rand von Rodaun angelegt, in Richtung Liesing, da der ursprüngliche Friedhof aus dem Jahr 1783 geschlossen wurde. Der alte Friedhof war im Zusammenhang mit der Erhebung Rodauns zur Pfarre angelegt worden und befand sich hinter dem damaligen Gemeindehaus in der [[Ketzergasse]]"}, {"kategorie": "", "text": "Die erste von mehreren Erweiterungen des Friedhofs fand 1878 statt, die letzte im Jahr 1963. Die heutige Aufbahrungshalle wurde zwischen 1962 und 1964 gebaut"}, {"kategorie": "", "text": "Der auf dem Gelände des Rodauner Friedhofs angelegte russische Soldatenfriedhof wurde von 1945 bis 1947 mit Gruppen- und Einzelgräbern von Angehörigen der Roten Armee belegt."}]'::jsonb, ''),
  ('siivaringa-friidhof', 'Siivaringa Friidhof', '', '', '', '', 'Sieveringer Friedhof', '[{"kategorie": "", "text": "Er umfasst eine Fläche von 36.787 Quadratmetern mit rund 5.300 Grabstellen, liegt malerisch auf einer Kuppe des [[Hackenbergs]] und dient als letzte Ruhestätte für zahlreiche prominente Persönlichkeiten"}, {"kategorie": "", "text": "Der heutige Sieveringer Friedhof wurde 1883 geweiht und verfügte bereits zu Beginn über eine Leichenkammer, einen Seziersaal sowie eine Totengräberwohnung"}, {"kategorie": "", "text": "Eine bedeutende bauliche Neuerung erfolgte 1980, als der Architekt Erich Boltenstern einen neuen Aufbahrungsraum errichtete. Dieser wurde von dem Künstler Hermann Bauch künstlerisch gestaltet, mit einem Altarkreuz, Bleiglasfenstern, Portalverglasungen und Mosaikarbeiten an der Stirnwand"}, {"kategorie": "", "text": "Der Sieveringer Friedhof ist nicht nur ein Ort der Ruhe, sondern beherbergt auch die Gräber zahlreicher prominenter Persönlichkeiten, darunter auch jenes von Anton Karas, dem bekannten Zitherspieler, Heurigenbesitzer und Komponisten der Titelmelodie des Films \"Der Dritte Mann\"."}]'::jsonb, ''),
  ('schdadlaua-friidhof', 'Schdadlaua Friidhof', '', '', '', '', 'Stadlauer Friedhof', '[{"kategorie": "", "text": "Der Friedhof  wurde 1875 errichtet und umfasst eine Fläche von 14.788 Quadratmetern mit etwa 2.300 Grabstellen. Er diente ursprünglich den Bewohnern des Vororts Stadlau, die zuvor in Kagran beerdigt wurden. Aufgrund der wachsenden Bevölkerung und gesundheitlicher Bedenken, insbesondere während mehrerer Epidemien, wurde der Bau eines eigenen Friedhofs beschlossen. Er wurde am 22. August 1875 vom Kagraner Pfarrer Andreas Huger geweiht"}, {"kategorie": "", "text": "Der Friedhof erfuhr mehrfach Erweiterungen, beginnend 1891 sowie in den Jahren 1915/16, 1925 und 1929. Eine neue Aufbahrungshalle wurde 1930 errichtet und nach dem Zweiten Weltkrieg instand gesetzt und erweitert"}, {"kategorie": "", "text": "Ein gusseisernes Kreuz, das ursprünglich 1876 errichtet wurde, wurde 1946 durch einen Orkan zerstört. Es wurde 1947 durch das „Heimkehrerkreuz“ ersetzt, das vom Bildhauer Josef Franz Riedl geschaffen wurde und an die gefallenen Stadlauer erinnert"}, {"kategorie": "", "text": "Im Laufe der 1980er Jahre kam es zu weiteren Renovierungen und Umgestaltungen, darunter ein neuer Aufbahrungsraum, der von Architekt Erich Boltenstern gestaltet wurde. Eine neue Einfriedungsmauer und Tore wurden entlang der [[Hardeggasse]] errichtet"}, {"kategorie": "", "text": "Die oberirdische Trasse der U-Bahn-Linie U2 verläuft nahe der nördlichen Umzäunung, und die Station [[Hardeggasse]] befindet sich in direkter Nähe."}]'::jsonb, ''),
  ('schdammasduafa-friidhef', 'Schdammasduafa Friidhef', '', '', '', '', 'Stammerdorfer Friedhöfe', '[{"kategorie": "", "text": "Der Stammersdorfer Pfarrfriedhof befand sich ursprünglich rund um die [[Stammersdorfer]] Kirche. Auf diesem Friedhof wurden die Bewohner von [[Stammersdorf]] und [[Strebersdorf]] beerdigt. Im Jahr 1833 wurde der Friedhof aufgelassen, und 1847 wurde das Gelände eingeebnet"}, {"kategorie": "", "text": "Nach der Schließung des Pfarrfriedhofs 1833 kauften die beiden Gemeinden Stammersdorf und Strebersdorf einen Weingarten außerhalb der Kirchhofsmauer, um einen neuen Friedhof anzulegen. Der Stammersdorfer Ortsfriedhof wurde am 1. Dezember 1833 durch den Schottenabt Sigismund Schultes eingeweiht. Ursprünglich sollte der Friedhof 1975 geschlossen werden, doch nach einer Volksbefragung wurde die Belegung des Friedhofs bis 1985 verlängert und die Schließung schließlich 1980 aufgehoben"}, {"kategorie": "", "text": "Der Stammersdorfer Zentralfriedhof wurde als Reaktion auf das Wachstum der Region errichtet, nachdem sich die Orte Jedlesee, Neu-Jedlersdorf, Donaufeld und Floridsdorf im Jahr 1894 zur Großgemeinde Floridsdorf zusammenschlossen. Eine der Bedingungen der Gemeindevertreter war die Auflassung der alten Ortsfriedhöfe und die Errichtung eines zentralen Friedhofs. Dafür wurden 1901 Grundstücke in Stammersdorf an der damaligen Gerasdorfer Bezirksstraße (heutige [[Stammersdorfer]] Straße) erworben. Nach der Weihe am 27. Mai 1903 wurde der Friedhof am 1. Juni 1903 eröffnet. Gleichzeitig wurden die Ortsfriedhöfe in Floridsdorf, Jedlesee und Donaufeld geschlossen. Der Friedhof verfügt über eine markante neugotische Einfahrtshalle"}, {"kategorie": "", "text": "Die Stammersdorfer Friedhöfe umfassen mehrere historisch bedeutsame Begräbnisstätten in Floridsdorf, die auf verschiedene Phasen der Ortsentwicklung zurückgehen. Der Stammersdorfer Ortsfriedhof und der Stammersdorfer Zentralfriedhof sind bis heute in Betrieb und wichtige Zeugnisse der lokalen Bestattungskultur."}]'::jsonb, ''),
  ('schdammasduafa-schdrossn', 'Schdammasduafa Schdrossn', '', '', '', '', 'Stammersdorfer Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsverbindung im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), die in den nördlichen Stadtteil [[Stammersdorf]] führt\""}, {"kategorie": "", "text": "Sie verbindet die zentraleren Teile von Floridsdorf mit den ländlicheren, traditionelleren Gegenden von Stammersdorf, das für seine Weinberge und [[Heurigen]] bekannt is"}, {"kategorie": "", "text": "Die Stammersdorfer Straße war früher als Gerasdorfer Bezirksstraße bekannt und spielte eine zentrale Rolle bei der Erschließung der Region um Stammersdorf. Im Jahr 1901 wurden Grundstücke entlang der Straße für die Errichtung des [[Stammersdorfer]] Zentralfriedhofs erworben. Dieser Friedhof, der 1903 eröffnet wurde, ersetzte die Ortsfriedhöfe von [[Floridsdorf]], [[Jedlesee]] und [[Donaufeld]]"}, {"kategorie": "", "text": "Eines der wichtigsten Wahrzeichen entlang der Straße ist die [[Stammerdorfer]] Kirche (Stammersdorfer Straße 35)"}, {"kategorie": "", "text": "Heute ist die Straße eine der Hauptachsen im Bezirk und dient sowohl als Wohnstraße als auch als Verkehrsader, die den städtischen und den ländlichen Charakter von Floridsdorf miteinander verbindet."}]'::jsonb, ''),
  ('suedwest-friidhof', 'Südwest Friidhof', '', '', '', '', 'Südwestfriedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 239.439 Quadratmetern und rund 25.500 Grabstellen ist der Südwestfriedhof der zweitgrößte Friedhof Wiens nach dem [[Zentralfriedhof]]"}, {"kategorie": "", "text": "Der Friedhof wurde aufgrund des wachsenden Platzmangels auf den bestehenden Friedhöfen der Bezirke 12 bis 16 errichtet. Die erste Bestattung fand am 20. Juli 1921 statt. Zu dieser Zeit wurde auch die Einsegnungs- und Aufbahrungshalle nach den Plänen der Architekten Erich Leischner und Friedrich Jäckel errichtet, ein eingeschoßiger Bau mit einem zentralen überhöhten Mittelrisalit"}, {"kategorie": "", "text": "Der Friedhof wurde im Laufe der Jahre mehrfach erweitert. 1960 wurde eine Kriegsgräberanlage geschaffen, in der 403 Kriegstote aus dem Garten des Altersheims Lainz bestattet wurden. In den 1970er Jahren entwarf der Architekt Erich Boltenstern eine neue Aufbahrungshalle im erweiterten Teil des Friedhofs"}, {"kategorie": "", "text": "Obwohl der Südwestfriedhof großflächig angelegt ist, gibt es nur elf ehrenhalber gewidmete Gräber, darunter die der österreichischen Kinder- und Jugendbuchautorin Vera-Ferra Mikura (1923-1997) und des Burgschauspielers Fred Liewehr (1909-1993)."}]'::jsonb, ''),
  ('siassnbrunna-friidhof', 'Siassnbrunna Friidhof', '', '', '', '', 'Süßenbrunner Friedhof', '[{"kategorie": "", "text": "Der 1893 geweihte Friedhof ist mit einer Fläche von 4.593 Quadratmetern einer der kleinsten städtischen Friedhöfe Wiens und verfügt über lediglich rund 400 Grabstellen"}, {"kategorie": "", "text": "Ursprünglich wurden die Verstorbenen aus Süßenbrunn auf dem Friedhof in Gerasdorf bestattet. Als dieser für epidemiologische Todesfälle als unzureichend angesehen wurde, wurde der Gemeinde Süßenbrunn im Jahr 1891 die Anlage eines eigenen Friedhofs nahegelegt. Der Süßenbrunner Friedhof wurde daraufhin am 22. Mai 1893 eingeweiht"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg erfuhr der Friedhof Erweiterungen. 1959 wurde der Aufbahrungsraum renoviert und mit einem Stirnwandaltar ausgestattet. Der erweiterte Teil des Friedhofs wurde am 30. Oktober 1987 geweiht"}, {"kategorie": "", "text": "Der Friedhof liegt im äußersten Norden der [[Donaustadt]], östlich von [[Süßenbrunn]], inmitten von Gemüsegärten und Feldern."}]'::jsonb, ''),
  ('leopoidaua-gasweak', 'Leopoidaua Gasweak', '', '', '', '', 'Leopoldauer Gaswerk', '[{"kategorie": "", "text": "Der Bau des Gaswerks wurde 1907/1908 vom Gemeinderat beschlossen, um den steigenden Energiebedarf Wiens zu decken. Die Anlage nahm am 17. Dezember 1911 die Gaserzeugung auf"}, {"kategorie": "", "text": "Am 16. August 1927 begann das Gaswerk Leopoldau mit der Wassergaserzeugung, was die Effizienz der Anlage erheblich steigerte. Ein weiterer Meilenstein war die Inbetriebnahme des Scheibengasbehälters Zwei am 3. Juni 1930"}, {"kategorie": "", "text": "Bereits während des [[Zweiten]] Weltkriegs wurde am 18. Jänner 1943 erstmals Erdgas verwendet, gemischt mit Stadtgas. Zwischen 1942 und 1945 befand sich auf dem Gelände des Gaswerks ein Zwangsarbeiterlager, in dem während des Zweiten Weltkriegs Zwangsarbeiter untergebracht waren, die in der Gaserzeugung eingesetzt wurden. Die Anlagen des Gaswerks wurden während des Krieges schwer beschädigt, aber nach dem Krieg wiederhergestellt"}, {"kategorie": "", "text": "Im Zuge der Umstellung auf Erdgas wurde der alte Kammerofen, der noch für die traditionelle Stadtgaserzeugung genutzt wurde, im August 1969 abgestellt. Die Abgabe des letzten Stadtgases erfolgte 1978, womit die Stadtgasproduktion endgültig eingestellt wurde"}, {"kategorie": "", "text": "Nach der Einstellung der Stadtgasproduktion wurden die Gasbehäter abgerissen, und das Gelände wurde in den 1980er Jahren in ein Fernwärmewerk umgewandelt."}]'::jsonb, ''),
  ('leopoidaua-plotz', 'Leopoidaua Plotz', '', '', '', '', 'Leopoldauer Platz', '[{"kategorie": "allg.", "text": "zentraler Platz im Stadtteil [[Leopoldau]], einem ländlich geprägten Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Der Leopoldauer Platz liegt im Herzen von Leopoldau, einem Stadtteil mit dörflichen Wurzeln, der 1904 nach Wien eingemeindet wurde. Als zentraler Ort des ehemaligen Dorfes war und ist der Leopoldauer Platz ein bedeutendes Element des öffentlichen Lebens in Leopoldau"}, {"kategorie": "", "text": "Am Leopoldauer Platz befindet sich die [[Pfarrkirche]] Leopoldau, die dem heiligen Leopold geweiht ist und das Ortsbild prägt"}, {"kategorie": "", "text": "Zudem befindet sich am leopoldauer Platz auch eine steinerne Statue des Hl. Leopold vom Ende des 17. Jahrhunderts (am östlichen Ende des Karl-Seidl-Parks)"}, {"kategorie": "", "text": "Der Platz ist verkehrstechnisch gut erschlossen und bietet den Anwohnern und Besuchern eine Anbindung an öffentliche Verkehrsmittel, sodass das Zentrum Wiens und andere Teile von [[Floridsdorf]] schnell erreichbar sind."}]'::jsonb, ''),
  ('pfoakiachn-leopoidau', 'Pfoakiachn Leopoidau', '', '', '', '', 'Pfarrkirche Leopoldau', '[{"kategorie": "", "text": "Die Kirche wurde im Lauf der Jahrhunderte mehrfach verkleinert und erweitert. Der heutige barocke Kirchenbau entstand 1696, nachdem die alte Kirche 1683 durch die Osmanen weitgehend zerstört worden war"}, {"kategorie": "", "text": "Der Kirchenbau von 1696 zeigt typische barocke Elemente wie den Volutengiebel an der Fassade und das Hauptportal. Über dem Seiteneingang steht eine Muttergottesstatue in einer Nische"}, {"kategorie": "", "text": "Die Kirche besitzt am Hochaltar eine eindrucksvolle Kreuzigungsgruppe (um 1700) sowie barocke Skulpturen des heiligen Florian und des heiligen Johannes Nepomuk. Eine besondere Verehrung gilt der Marienstatue mit Kind (Mitte 14. Jahrhundert) am linken Seitenaltar"}, {"kategorie": "", "text": "Die Barockorgel wurde 1817 von den Barmherzigen Brüdern erworben und stammt von Johann Hencke (1736). Die Ausmalung der Kirche in barocker Manier wurde 1952 erneuert"}, {"kategorie": "", "text": "In der Parkanlage am Ostende des Platzes steht eine Statue des heiligen Leopold (zweite Hälfte des 17. Jahrhunderts) sowie eine Johannes-Nepomuk-Statue (erste Hälfte des 18. Jahrhunderts)"}, {"kategorie": "", "text": "Mit ihrer beeindruckenden Architektur und den wertvollen Kunstwerken ist die Kirche ein zentrales religiöses und kulturelles Wahrzeichen des Stadtteils [[Leopoldau]]."}]'::jsonb, ''),
  ('atzgasduafa-schdrossn', 'Atzgasduafa Schdrossn', '', '', '', '', 'Atzgersdorfer Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 12. und 23. Wiener Gemeindebezirk ([[Meidling]] und [[Liesing]]), die den historischen Stadtteil [[Atzgersdorf]] mit anderen Bezirksteilen verbindet\""}, {"kategorie": "", "text": "Sie beginnt bei der [[Fasangartenstraße]] und endet im Bereich der [[Breitenfurter]] Straße"}, {"kategorie": "", "text": "Heute dient die Atzgersdorfer Straße als eine zentrale Verkehrsverbindung im 23. Bezirk und ist gesäumt von Wohnhäusern, Geschäften und öffentlichen Einrichtungen"}, {"kategorie": "", "text": "Sie verbindet das städtische [[Liesing]] mit dem eher dörflich geprägten [[Atzgersdorf]] und bildet eine wichtige Achse für Pendler und den öffentlichen Verkehr."}]'::jsonb, ''),
  ('donaufoeoeda-schdrossn', 'Donaufööda Schdrossn', '', '', '', '', 'Donaufelderstraße', '[{"kategorie": "allg.", "text": "\"wichtige Hauptverkehrsstraße im 21. und 22. Wiener Gemeindebezirk ([[Floridsdorf]] und [[Donaustadt]]), welche die Stadtteile [[Donaufeld]], [[Leopoldau]] und [[Kagran]] miteinander verebindet\""}, {"kategorie": "", "text": "Die Donaufelder Straße beginnt im Westen in der Nähe des [[Floridsdorfer]] Bahnhofs und verläuft nach Osten, wo sie schließlich in den 22. Wiener Bezirk, [[Donaustadt]], übergeht"}, {"kategorie": "", "text": "Die Donaufelder Straße hat ihren Namen von dem Stadtteil [[Donaufeld]], der im späten 19. Jahrhundert eigenständig war, bevor er 1894 mit Floridsdorf vereinigt wurde"}, {"kategorie": "", "text": "Die Straße ist gesäumt von einer Mischung aus Wohn- und Geschäftsbauten. In den letzten Jahren hat sich die Donaufelder Straße aufgrund der städtischen Entwicklung und der wachsenden Bevölkerungsdichte in Donaufeld und Kagran zu einem bedeutenden Wohn- und Geschäftsviertel entwickelt."}]'::jsonb, ''),
  ('cisleithanische-reichshoeftn', 'Cisleithanische Reichshöftn', '', '', '', '', 'Cisleithanische Reichshälfte', '[{"kategorie": "allg.", "text": "\"inoffizieller Name für die österreichische Reichshälfte der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Es bezeichnete die Gebiete der [[Doppelmonarchie]], die westlich der Leitha, eines Nebenflusses der Donau, lagen. Diese Regionen standen unter der Verwaltung des österreichischen Kaisers und wurden oft auch als \"Die im Reichsrat vertretenen Königreiche und Länder\" bezeichnet"}, {"kategorie": "", "text": "Die Cisleithanische Reichshälfte umfasste viele [[Kronländer]], darunter Österreich, Böhmen, Mähren, Galizien, Schlesien, und andere. Im Gegensatz dazu stand die [[Transleithanische]] Reichshälfte, welche die ungarische Reichshälfte bezeichnete, also die Gebiete östlich der Leitha, unter der Verwaltung des ungarischen Königs"}, {"kategorie": "", "text": "Die Cisleithanische Reichshälfte ([[Cisleithanien]]) hatte eine eigene Verwaltung, ein Parlament (den [[Reichsrat]]), und teilweise eigene Gesetze, war aber über den gemeinsamen Monarchen und bestimmte Ministerien (wie Außenpolitik, Kriegswesen, Finanzen) mit [[Transleithanien]] verbunden."}]'::jsonb, ''),
  ('transleithanische-reichshoeftn', 'Transleithanische Reichshöftn', '', '', '', '', 'Transleithanische Reichshälfte', '[{"kategorie": "allg.", "text": "\"inoffizieller Name für die ungarische Reichshälfte der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Es bezeichnete die Gebiete, die östlich der Leitha, eines Nebenflusses der Donau, lagen. Der Begriff steht im Gegensatz zur [[Cisleithanischen]] Reichshälfte, der österreichischen Reichshälfte, die westlich der Leitha lag"}, {"kategorie": "", "text": "Die Transleithanische Reichshälfte umfasste vor allem das [[Königreich]] Ungarn sowie die ihm angeschlossenen Gebiete, wie Kroatien-Slawonien und Siebenbürgen"}, {"kategorie": "", "text": "Diese Gebiete hatten nach dem [[Ausgleich]] von 1867 weitgehende Autonomie und wurden von der ungarischen Regierung in Budapest verwaltet, während der ungarische König (in Personalunion auch Kaiser von Österreich) die oberste Autorität blieb"}, {"kategorie": "", "text": "Auch wenn Ungarn eine eigene Verfassung und Regierung hatte, blieben bestimmte Bereiche (wie Außenpolitik, Militär und Finanzen) zwischen Österreich und Ungarn gemeinsam geregelt"}, {"kategorie": "", "text": "Der Begriff \"Transleithanische Reichshälftze\" oder [[Transleithanien]] wurde hauptsächlich in Verwaltung und Politik verwendet, um die territoriale Unterscheidung zwischen den beiden Reichsteilen Österreich-Ungarns zu verdeutlichen."}]'::jsonb, ''),
  ('republik-oestarreich', 'Republik Östarreich', '', '', '', '', 'Republik Österreich', '[{"kategorie": "allg.", "text": "\"demokratischer Staat in Mitteleuropa, der nach dem Ende der [[Habsburgermonarchie]] im Jahr 1918 gegründet wurde\""}, {"kategorie": "", "text": "Die Republik Österreich entstand nach dem Zusammenbruch des österreichisch-ungarischen Kaiserreichs ([[Kaiserreich]] Österreich-Ungarn) infolge des [[Ersten]] Weltkriegs. Am 12. November 1918 wurde die Republik offiziell ausgerufen und die [[Habsburgermonarchie]] abgeschafft"}, {"kategorie": "", "text": "In ihrer Geschichte gab es zwei Hauptphasen: (i) [[Erste]] Republik (1918–1938): Diese Phase begann mit der Ausrufung der Republik und endete 1938 mit dem [[Anschluss]] Österreichs an das nationalsozialistische [[Deutsche]] Reich. In dieser Zeit durchlief Österreich politisch und wirtschaftlich schwierige Zeiten, einschließlich des [[Bürgerkriegs]] von 1934 und der Errichtung eines autoritären [[Ständestaates]] unter der Führung von Engelbert Dollfuß;  (ii) [[Zweite]] Republik (seit 1945): Nach dem [[Zweiten]] Weltkrieg wurde Österreich am 27. April 1945 erneut zur Republik erklärt. Die Zweite Republik basiert auf der 1920 eingeführten Verfassung (in der Fassung von 1929) und markierte den Neuanfang als unabhängiger, neutraler Staat. 1955 erlangte Österreich durch den [[Staatsvertrag]] seine volle Souveränität zurück und erklärte sich dauerhaft zur [[immerwährenden]] Neutralität"}, {"kategorie": "", "text": "Österreich ist heute ein föderaler, parlamentarischer demokratischer Staat, bestehend aus neun Bundesländern, und seit 1995 Mitglied der Europäischen Union. Der Bundespräsident ist das Staatsoberhaupt, während der Bundeskanzler die Regierung leitet. Die Republik steht für eine pluralistische Gesellschaft mit einem starken Sozialstaat und einer bedeutenden wirtschaftlichen Stellung in Europa."}]'::jsonb, ''),
  ('waehrungsrefoam-von-1892', 'Währungsrefoam von 1892', '', '', '', '', 'Währungsreform von 1892', '[{"kategorie": "allg.", "text": "\"bedeutende finanzpolitische Maßnahme innerhalb von [[Österreich-Ungarn]], welche die Einführung der [[Krone]] als neue Währungseinheit zur Folge hatte und den [[Gulden]] ersetzte\""}, {"kategorie": "", "text": "Diese Reform war Teil eines größeren Modernisierungsprozesses der Wirtschaft des [[Habsburgerreichs]] und brachte eine Umstellung auf den Goldstandard, was die Stabilität und das Vertrauen in die neue Währung stärken sollte"}, {"kategorie": "", "text": "Die Währungsreform von 1892 war somit ein zentraler Schritt zur wirtschaftlichen Modernisierung der [[Doppelmonarchie]] Österreich-Ungarn. Sie brachte eine stabilere und international anerkannte Währung, die das Vertrauen der Bevölkerung und der internationalen Märkte stärkte"}, {"kategorie": "", "text": "Die Krone blieb bis zum Ende der Monarchie 1918 in Gebrauch und wurde in den Nachfolgestaaten für einige Zeit weiterhin verwendet, bis sie durch neue Währungen ersetzt wurde."}]'::jsonb, ''),
  ('hoofn-alban', 'Hoofn Alban', '', '', '', '', 'Hafen Albern', '[{"kategorie": "", "text": "Er wurde in den 1930er Jahren errichtet und war ursprünglich Teil der Pläne zur Erweiterung des Wiener Hafensystems"}, {"kategorie": "", "text": "Eine besondere Bedeutung erlangte der Alberner Hafen durch seine großen Getreidesilos, die bis heute als markantes Wahrzeichen des Hafens gelten"}, {"kategorie": "", "text": "Neben seiner industriellen Nutzung ist der Hafen auch historisch interessant, da er in der Nähe des [[Friedhofs]] der Namenlosen liegt, auf dem angeschwemmte Wasserleichen bestattet wurden"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs spielte der Alberner Hafen eine Rolle in der militärischen Logistik, und seine Anlagen wurden teilweise beschädigt"}, {"kategorie": "", "text": "Heute ist er weiterhin in Betrieb und ein wichtiger Bestandteil der [[Wiener]] Hafeninfrastruktur, insbesondere für den Güterverkehr auf der Donau."}]'::jsonb, ''),
  ('albana-hoofn', 'Albana Hoofn', '', '', '', '', 'Alberner Hafen', '[{"kategorie": "", "text": "Er wurde in den 1930er Jahren errichtet und war ursprünglich Teil der Pläne zur Erweiterung des Wiener Hafensystems"}, {"kategorie": "", "text": "Eine besondere Bedeutung erlangte der Alberner Hafen durch seine großen Getreidesilos, die bis heute als markantes Wahrzeichen des Hafens gelten"}, {"kategorie": "", "text": "Neben seiner industriellen Nutzung ist der Hafen auch historisch interessant, da er in der Nähe des [[Friedhofs]] der Namenlosen liegt, auf dem angeschwemmte Wasserleichen bestattet wurden"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs spielte der Alberner Hafen eine Rolle in der militärischen Logistik, und seine Anlagen wurden teilweise beschädigt"}, {"kategorie": "", "text": "Heute ist er weiterhin in Betrieb und ein wichtiger Bestandteil der [[Wiener]] Hafeninfrastruktur, insbesondere für den Güterverkehr auf der Donau."}]'::jsonb, ''),
  ('wiina-hoofninfrastruktua', 'Wiina Hoofninfrastruktua', '', '', '', '', 'Wiener Hafeninfrastruktur', '[{"kategorie": "allg.", "text": "\"Gesamtheit der Häfen, Umschlagsanlagen, Lagerstätten und Verkehrswege, die in Wien entlang der [[Donau]] und des [[Donaukanals]] für den Güterverkehr, die Schifffahrt und logistische Dienstleistungen genutzt werden\""}, {"kategorie": "", "text": "Sie spielt eine zentrale Rolle für den Warenumschlag und die Logistik in der Region und verbindet Wien mit internationalen Wasserstraßen, insbesondere der [[Donau]], die eine wichtige Verkehrsader zwischen West- und Osteuropa darstellt"}, {"kategorie": "", "text": "Zu den wichtigsten Bestandteilen der Wiener Hafeninfrastruktur gehören: (i) [[Freudenauer]] Hafen (der größte und wichtigste Hafen Wiens, der für den Umschlag von Containern, Schüttgütern und Massengütern genutzt wird), (ii) [[Alberner]] Hafen: (ein bedeutender Frachthafen, spezialisiert auf den Umschlag von Getreide und Schüttgütern, mit großen Getreidesilos), (iii) [[Winterhafen]] (historisch bedeutsam, heute eher für kleinere Schiffe und Freizeitboote genutzt), sowie (iv) [[Ölhafen]] Lobau (dient dem Umschlag von Öl und Mineralölprodukten und spielt eine zentrale Rolle in der Energieversorgung)"}, {"kategorie": "", "text": "Die Wiener Hafeninfrastruktur ist nicht nur über den Wasserweg mit den Ländern entlang der Donau verbunden, sondern auch durch Straßen- und Schienenverkehr, was ihre Bedeutung als multimodales Logistikzentrum verstärkt. Diese Infrastruktur ermöglicht effiziente Warenströme in und aus der Stadt und unterstützt die internationale Vernetzung Wiens als Wirtschaftsstandort."}]'::jsonb, ''),
  ('hoofn-freidenau', 'Hoofn Freidenau', '', '', '', '', 'Hafen Freudenau', '[{"kategorie": "", "text": "Er befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) entlang der [[Donau]] und spielt eine entscheidende Rolle im Warenumschlag und in der Logistik. Der Hafen ist spezialisiert auf den Umschlag von Containern, Schüttgütern (wie Kies, Sand, und Getreide) sowie Massengütern und ist ein wichtiger Knotenpunkt für den Handel auf der Donau, die eine bedeutende Wasserstraße zwischen West- und Osteuropa darstellt"}, {"kategorie": "", "text": "Der Freudenauer Hafen ist Teil des Hafen Wien-Netzwerks und verfügt über gut ausgebaute multimodale Verbindungen, darunter direkte Anbindungen an das Straßennetz und das Schienennetz, was ihn zu einem wichtigen Logistikzentrum macht"}, {"kategorie": "", "text": "Durch seine Lage an der Donau und die moderne Infrastruktur spielt der Freudenauer Hafen eine Schlüsselrolle im internationalen Güterverkehr, insbesondere im Handel mit Ländern entlang der Donau"}, {"kategorie": "", "text": "Zusätzlich zum Frachtverkehr werden im Hafen auch Dienstleistungen wie Lagerung, Verladung und Transport organisiert, was ihn zu einem integralen Bestandteil der Wiener Wirtschaft macht."}]'::jsonb, ''),
  ('freidenaua-wintahoofn', 'Freidenaua Wintahoofn', '', '', '', '', 'Freudenauer Winterhafen', '[{"kategorie": "allg.", "text": "\"bedeutender Teil des [[Wiener]] Hafensystems im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Der Hafen wurde nach der [[Donauregulierung]] von 1875 am rechten Ufer der Donau angelegt. Dieser Hafenbereich wurde ab 1889 ausgebaut, um Schiffen im Winter Schutz vor Hochwasser und Eis zu bieten, und schließlich 1902 eröffnet"}, {"kategorie": "", "text": "Ursprünglich bestand der Freudenauer Winterhafen aus zwei Teilen: dem Haupthafen und einem kleineren Seitenhafen. Der Seitenhafen wurde jedoch in den 1960er und 1970er Jahren zugeschüttet, um Platz für eine Zollfreizone zu schaffen"}, {"kategorie": "", "text": "In der Nähe des Hafens befinden sich wichtige Infrastrukturen, darunter die [[Freudenauer]] Hafenbrücke und das 1998 fertiggestellte [[Kraftwerk]] Freudenau"}, {"kategorie": "", "text": "Heute ist der Freudenauer Winterhafen Teil des größten trimodalen Güterverkehrszentrums Österreichs, das den Transport von Gütern per Schiff, Straße und Schiene vernetzt."}]'::jsonb, ''),
  ('oeoehoofn-lobau', 'Ööhoofn Lobau', '', '', '', '', 'Ölhafen Lobau', '[{"kategorie": "allg.", "text": "\"spezialisierter Hafen in Wien, der sich im 22. Wiener Gemeindebezirk Donaustadt in der Nähe des Nationalparks Donau-Auen ([[Lobau]]) befindet\""}, {"kategorie": "", "text": "Er ist ein zentraler Umschlagplatz für Mineralölprodukte und spielt eine wichtige Rolle in der Energieversorgung Österreichs. Der Ölhafen dient hauptsächlich der Lagerung, dem Umschlag und der Verteilung von Erdöl und seinen Derivaten, die über die Donau und Pipelines transportiert werden"}, {"kategorie": "", "text": "Der Hafen ist mit großen Tanklagern ausgestattet, in denen Erdölprodukte zwischengelagert werden, bevor sie über das Straßen- und Schienennetz oder über Pipelines weiterverteilt werden. Der Ölhafen Lobau ist eng mit der Raffinerie Schwechat, einer der größten Erdölraffinerien Österreichs, verbunden, was seine strategische Bedeutung für die nationale Energieversorgung unterstreicht"}, {"kategorie": "", "text": "Aufgrund seiner Lage und Funktion ist der Ölhafen streng abgesichert und spielt eine Schlüsselrolle im Logistik- und Versorgungssystem von Mineralölprodukten für Wien und ganz Österreich."}]'::jsonb, ''),
  ('sechshausa-schdrossn', 'Sechshausa Schdrossn', '', '', '', '', 'Sechshauser Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsachse, die nach dem Vorort [[Sechshaus]] benannt wurde\""}, {"kategorie": "", "text": "Die Straße erhielt ihren Namen am 13. Juli 1894 und war zuvor als Sechshauser Hauptstraße bekannt"}, {"kategorie": "", "text": "Im 19. Jahrhundert bildete sie die nördliche Grenze des Vororts Sechshaus, der bis zum [[Wienfluss]] reichte, sowie die südliche Begrenzung der Vororte Fünfhaus und Rudolfsheim"}, {"kategorie": "", "text": "Nach der Eingemeindung der Vororte 1890/1892 veränderte sich das Erscheinungsbild der Sechshauser Straße: Anstelle alter Vororthäuser wurden zunehmend großstädtische, überwiegend späthistoristische und secessionistische Miethäuser errichtet"}, {"kategorie": "", "text": "Die Methodistenkirche an der Sechshauser Straße 56 ist ein markantes Bauwerk. Die Methodistengemeinde Rudolfsheim, gegründet 1897, ist die zweitälteste in Wien"}, {"kategorie": "", "text": "Heute ist die Sechshauser Straße sowohl eine wichtige Verkehrsachse als auch eine Geschäftsstraße, welche von Wohnhäusern, Geschäften, Restaurants und Dienstleistungsbetrieben gesäumt ist und den städtischen Charakter des Bezirks widerspiegelt."}]'::jsonb, ''),
  ('vataeulakreis-favoritn', 'Vatäulakreis Favoritn', '', '', '', '', 'Verteilerkreis Favoriten', '[{"kategorie": "allg.", "text": "\"großer Kreisverkehr im 10. Wiener Gemeindebezirk ([[Favoriten]]), der als wichtiger Verkehrsknotenpunkt dient (offizieller Straßenname: [[Altes Landgut]])\""}, {"kategorie": "", "text": "Er verbindet mehrere Hauptstraßen, darunter die [[Südosttangente]] (A23) und die [[Favoritenstraße]]"}, {"kategorie": "", "text": "Er wurde in den 1970er Jahren als Teil des umfassenden Verkehrskonzepts der Stadt Wien errichtet, um den wachsenden Verkehr besser zu organisieren"}, {"kategorie": "", "text": "Der Verteilerkreis ist sowohl für den Individual- als auch für den öffentlichen Verkehr von großer Bedeutung, da er zahlreiche Verkehrsrouten im Süden Wiens miteinander verknüpft"}, {"kategorie": "", "text": "Heute befinden sich direkt am Verteilerkreis Favoriten zudem auch die größte Fachhochschule Wiens, das Fußballstadion des [[FK]] Austria Wien sowie das [[Laaerbergbad]]."}]'::jsonb, ''),
  ('hadasduaf-weidlingau', 'Hadasduaf-Weidlingau', '', '', '', '', 'Hadersdorf-Weidlingau', '[{"kategorie": "allg.", "text": "\"Stadtteil im 14. Wiener Gemeindebezirk ([[Penzing]])\""}, {"kategorie": "", "text": "Die Orte Hadersdorf und Weidlingau wurden 1850 zur Ortsgemeinde Hadersdorf-Weidlingau vereinigt und am 15. Oktober 1938 nach Wien eingemeindet"}, {"kategorie": "", "text": "Die Gemeinde umfasst mehrere Ortsteile, darunter [[Mariabrunn]], sowie Rotten wie Hainbach, Steinbach und Knödelhütte"}, {"kategorie": "", "text": "Historisch gesehen gehörte auch ein Teil von [[Auhof]] dazu, der später größtenteils dem 13. Bezirk Hietzing zugeordnet wurde"}, {"kategorie": "", "text": "Zwischen 1954 und 1956 war Hadersdorf-Weidlingau kurzzeitig Teil des 23. Bezirks ([[Liesing]]), bevor er endgültig zum 14. Bezirk zurückkehrte"}, {"kategorie": "", "text": "Im Volksmund wird Hadersdorf-Weidlingau von den Wienern gerne auch als [[Hawei]] bezeichnet. \"Hawei\" liegt liegt am westlichen Stadtrand von Wien im [[Wienerwald]] und grenzt an die niederösterreichischen Gemeinden Purkersdorf, Mauerbach und Klosterneuburg"}, {"kategorie": "", "text": "Aufgrund seiner Lage ist \"Hawei\" ein beliebter Ausgangspunkt für städtische Wanderwege. Durch den Ort fließen der [[Mauerbach]] und der [[Wienfluss]]"}, {"kategorie": "", "text": "Im östlichen Teil von Hadersdorf-Weidlingau befindet sich das [[Retentionsbecken]] Auhof, ein Sumpfgebiet, das als Hochwasserschutz für Wien dient, da es die Wasserfluten von Wienfluss und Mauerbach auffängt. Im westlichen Teil liegt die [[Hohe-Wand-Wiese]], eine von Wiens beiden Skipisten, und südlich des Ortes liegt der [[Lainzer]] Tiergarten, ein bedeutendes Naherholungsgebiet für die Wiener."}]'::jsonb, ''),
  ('retentionsbeckn-auhof', 'Retentionsbeckn Auhof', '', '', '', '', 'Retentionsbecken Auhof', '[{"kategorie": "allg.", "text": "\"Hochwasserrückhaltebecken im Westen Wiens, im 14. Bezirk ([[Penzing]]) im Stadtteil [[Auhof]], das dazu dient, den [[Mauerbach]] und den [[Wienfluss]] bei starken Regenfällen oder Hochwasser zu regulieren\""}, {"kategorie": "", "text": "Das Becken fängt überschüssiges Wasser auf, um Überflutungen in den tiefer gelegenen Stadtteilen und im Wiener Stadtgebiet zu verhindern"}, {"kategorie": "", "text": "Es liegt nahe dem Mündungsbereich des Mauerbachs in den Wienfluss und spielt eine zentrale Rolle im Hochwasserschutz der Stadt Wien"}, {"kategorie": "", "text": "Das Retentionsbecken Auhof ist in der Regel leer und wird nur bei Hochwasser geflutet. Es ist Teil eines umfassenden Systems von Hochwasserschutzmaßnahmen, das die Sicherheit und Infrastruktur der Stadt schützt"}]'::jsonb, ''),
  ('rueckhoitebeckn-auhof', 'Rückhoitebeckn Auhof', '', '', '', '', 'Rückhaltebecken Auhof', '[{"kategorie": "allg.", "text": "\"Wasserretentionsbecken im Westen Wiens, im 14. Bezirk ([[Penzing]]) im Stadtteil [[Auhof]], das dazu dient, den [[Mauerbach]] und den [[Wienfluss]] bei starken Regenfällen oder Hochwasser zu regulieren\""}, {"kategorie": "", "text": "Das Becken fängt überschüssiges Wasser auf, um Überflutungen in den tiefer gelegenen Stadtteilen und im Wiener Stadtgebiet zu verhindern"}, {"kategorie": "", "text": "Es liegt nahe dem Mündungsbereich des [[Mauerbachs]] in den Wienfluss und spielt eine zentrale Rolle im Hochwasserschutz der Stadt Wien"}, {"kategorie": "", "text": "Das Rückhaltebecken Auhof ist in der Regel leer und wird nur bei Hochwasser geflutet. Es ist Teil eines umfassenden Systems von Hochwasserschutzmaßnahmen, das die Sicherheit und Infrastruktur der Stadt schützt (siehe [[Grünauer Bach]])"}]'::jsonb, ''),
  ('hoche-waund-wiisn', 'Hoche-Waund-Wiisn', '', '', '', '', 'Hohe-Wand-Wiese', '[{"kategorie": "allg.", "text": "\"Skipiste im 14. Wiener Gemeindebezirk ([[Penzing]]), Katastralgemeinde [[Hadersdorf]], die neben der [[Dollwiese]] im 13. Bezirk ([[Hietzing]]) eine der zwei Skipisten in Wien darstellt\""}, {"kategorie": "", "text": "Die Piste ist etwa 400 Meter lang, verfügt über einen Schlepplift (seit 2016 durch ein Förderband ersetzt), eine Beschneiungsanlage und Flutlichtbeleuchtung und wird als blaue Piste eingestuft, da das Gefälle maximal 25 % beträgt"}, {"kategorie": "", "text": "Historisch bedeutend ist die Hohe-Wand-Wiese durch ihre Rolle im Wintersport: Hier wurde 1967 der erste Parallelslalom der Skigeschichte ausgetragen, und 1986 fand ein Weltcup-Parallelslalom unter Flutlicht statt. Die Piste ist seit 1957 im Besitz der Stadt Wien und wurde als Erholungsgebiet gewidmet"}, {"kategorie": "", "text": "Neben der Nutzung im Winter gibt es seit 2006 eine Sommerrodelbahn auf der Hohe-Wand-Wiese, und seit der Saison 2016/17 ermöglichen Dryslope-Kunststoffmatten Skifahren auch ohne Schnee."}]'::jsonb, ''),
  ('oba-sankt-veit', 'Oba-Sankt-Veit', '', '', '', '', 'Ober-St.-Veit', '[{"kategorie": "allg.", "text": "\"Stadtteil im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Ober-Sankt-Veit ist einer der ältesten und geschichtsträchtigsten Teile des Bezirks. Er liegt am westlichen Rand Wiens, an den Hängen des [[Wienerwaldes]], und zeichnet sich durch seine ruhige, grüne Umgebung sowie eine Mischung aus städtischer und dörflicher Struktur aus"}, {"kategorie": "", "text": "Ober-Sankt-Veit wird urkundlich erstmals im 12. Jahrhundert erwähnt und war ursprünglich ein kleines Dorf. Der Name „Sankt Veit“ leitet sich von der Pfarrkirche St. Veit ab, die dem heiligen Veit geweiht ist und eine der ältesten Kirchen in Wien darstellt. Der Zusatz „Ober“ dient zur Unterscheidung von [[Unter-Sankt-Veit]], das sich weiter östlich in Richtung der Stadt befindet"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wuchs Ober-Sankt-Veit zu einem beliebten Wohn- und Erholungsort heran, insbesondere durch seine Nähe zum [[Lainzer]] Tiergarten und den [[Wienerwald]]"}, {"kategorie": "", "text": "Der Stadtteil zeichnet sich durch eine abwechslungsreiche Architektur aus, die von historischen Gebäuden, alten Bauernhäusern bis hin zu modernen Villen und Wohnanlagen reicht. Besonders bekannt ist Ober-Sankt-Veit für seine eleganten Villen aus der Gründerzeit und dem frühen 20. Jahrhundert, die von wohlhabenden Wienern als Sommerresidenzen genutzt wurden"}, {"kategorie": "", "text": "Die [[Pfarrkirche]] Ober-Sankt-Veit ist eines der wichtigsten Wahrzeichen des Stadtteils. Sie wurde im Barockstil errichtet und prägt das historische Zentrum von Ober-Sankt-Veit. Rund um die Kirche befinden sich alte Gassen, die dem Stadtteil seinen charmanten, fast dörflichen Charakter verleihen"}, {"kategorie": "", "text": "Der Stadtteil liegt etwas erhöht, was bedeutet, dass viele Häuser in Ober-Sankt-Veit einen guten Ausblick auf Wien bieten. Die sanfte Hügellandschaft und die vielen Grünflächen tragen zur hohen Lebensqualität in diesem Gebiet bei."}]'::jsonb, ''),
  ('unta-sankt-veit', 'Unta-Sankt-Veit', '', '', '', '', 'Unter-St.-Veit', '[{"kategorie": "allg.", "text": "\"Stadtteil im 13. Wiener Gemeindebezirk ([[Hietzing]]), welcher westlich des [[Wienflusses]] und östlich von [[Ober-Sankt-Veit]] liegt\""}, {"kategorie": "", "text": "Ursprünglich gehörte das Gebiet bis 1867 zur Gemeinde St. Veit an der Wien, die im späteren [[Ober-Sankt-Veit]] ihr Zentrum hatte. Unter-Sankt-Veit entwickelte sich im 19. Jahrhundert als eigenständige Siedlung, geprägt durch den Einfluss von Gewerbe und Handwerk, während in Ober-Sankt-Veit vor allem die Landwirtschaft dominierte"}, {"kategorie": "", "text": "Im 15. Jahrhundert litt St. Veit unter den Angriffen der Truppen des ungarischen Königs Matthias Corvinus und wurde in den Türkenbelagerungen Wiens verwüstet. Im Bereich des heutigen Unter-Sankt-Veit gab es zu dieser Zeit nur wenige erwähnenswerte Strukturen, darunter die Feldmühle, die 1568 erstmals urkundlich erwähnt wurde"}, {"kategorie": "", "text": "Anfang des 19. Jahrhunderts ließ der Grundherr, der Wiener Erzbischof, Bauparzellen abstecken, um das Gebiet zu entwickeln. So entstand eine Siedlung, die bald den Namen „Neudörfl“ erhielt und den Kern von Unter-Sankt-Veit bildete, das sich um die heutige [[Feldmühlgasse]] und [[Hietzinger]] Hauptstraße ausdehnte"}, {"kategorie": "", "text": "Die Interessen von Ober- und Unter-Sankt-Veit waren oft unterschiedlich, was zu Spannungen zwischen den beiden Teilen führte. Während Ober-Sankt-Veit von der Landwirtschaft geprägt war, siedelten sich in Unter-Sankt-Veit vor allem Gewerbe- und Handwerksbetriebe an. Diese Differenzen führten schließlich dazu, dass die beiden Orte ihre Trennung anstrebten, die im Jahr 1867 von Kaiser [[Franz]] Joseph I. genehmigt wurde"}, {"kategorie": "", "text": "Nach der Trennung wurde Unter-Sankt-Veit für zwanzig Jahre autonom, bis es mit dem niederösterreichischen Gesetz von 1890 gemeinsam mit fast dem gesamten heutigen [[Hietzing]] in die Stadt Wien eingemeindet wurde"}, {"kategorie": "", "text": "Von 1945 bis 1955 befand sich Unter-Sankt-Veit im britischen Sektor Wiens, während die Stadt in vier [[Besatzungszonen]] unterteilt war. Seit dieser Zeit hat sich Unter-Sankt-Veit zu einem ruhigen, gehobenen Wohngebiet entwickelt, das sich durch seine Villen, gepflegten Straßen und die Nähe zu Grünflächen wie dem [[Schlosspark]] Schönbrunn und dem [[Lainzer]] Tiergarten auszeichnet"}]'::jsonb, ''),
  ('sankt-veit-gossn', 'Sankt-Veit-Gossn', '', '', '', '', 'St.-Veit-Gasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 13. Wiener Gemeindebezirk Hietzing, die sich durch die Stadtteile [[Unter-Sankt-Veit]] und [[Ober-Sankt-Veit]] von der [[Hietzinger]] Hauptstraße bis zur [[Stadlergasse]] zieht und nach dem ehemaligen Vorort \"St. Veit\" benannt ist\""}, {"kategorie": "", "text": "Die Ortschaft St. Veit ist erstmals in einer Urkunde von circa 1195 nachzuweisen. Ab dem 14. Jahrhundert wird der Ort \"Auf der Wien\" oder \"An der Wien\" genannt. Die [[Ober-St]].-Veiter Kirche wird urkundlich erst im 13. Jahrhundert erwähnt. Das ausgedehnte Ortsgebiet reichte von den Abhängen des [[Lainzer]] Tiergarten, an denen bis ins 19. Jahrhundert Wein gebaut wurde, bis zum [[Wienfluss]] einerseits und bis etwa zur heutigen [[Lainzer]] Straße andererseits und umfasste insbesondere das \"Veitinger Feld\" mit seiner reichen Gras- und Ackerbauwirtschaft"}, {"kategorie": "", "text": "Der Name St.-Veit-Gasse bezieht sich auf den heiligen Veit (lateinisch: Vitus), dem die Kirche St. Veit an der Wien (heute [[Ober-Sankt-Veiter-Kirche]]) geweiht ist"}, {"kategorie": "", "text": "Die Straße selbst hat eine lange Tradition und führt durch den historischen Kern des früheren Dorfs St. Veit, das im Mittelalter entstand und später in die Stadt Wien eingemeindet wurde"}, {"kategorie": "", "text": "Entlang der St.-Veit-Gasse finden sich verschiedene historische und moderne Gebäude, die den besonderen architektonischen Charakter von Hietzing widerspiegeln. Viele der Villen und Häuser entlang der Straße stammen aus dem 19. und frühen 20. Jahrhundert und stehen oft unter Denkmalschutz, was den historischen Wert der Gasse unterstreicht."}]'::jsonb, ''),
  ('unta-sankt-veita-kiachn', 'Unta-Sankt-Veita-Kiachn', '', '', '', '', 'Unter-St.-Veiter-Kirche', '[{"kategorie": "", "text": "Ursprünglich als kleine Landkirche erbaut, hat sie eine lange und bedeutende Geschichte. Die Kirche diente zunächst als Expositurkirche und wurde am 1. Jänner 1968 zur Pfarrkirche erhoben"}, {"kategorie": "", "text": "Die erste Kirche an dieser Stelle wurde zwischen 1862 und 1865 von Baumeister Josef Kopf errichtet. Anlass für den Bau war der Dank der Dorfbewohner dafür, dass ein Großteil der Häuser von Unter-Sankt-Veit während eines Feuers im Jahr 1860 verschont blieb. Die Kirche wurde 1867 geweiht"}, {"kategorie": "", "text": "Die ursprüngliche Kirche wurde 1965 abgerissen, um Platz für einen modernen Neubau zu schaffen, der zwischen 1965 und 1967 unter der Leitung des Architekten Anton Steflicek errichtet wurde. Die Grundsteinlegung erfolgte am 8. November 1965, und die neue Kirche wurde am 9. Juli 1967 feierlich geweiht"}, {"kategorie": "", "text": "Der Neubau zeichnet sich durch seine schlichte, moderne Architektur aus, die eine funktionale und spirituelle Atmosphäre schafft. Ein besonderes Highlight im Innenraum ist das Altarfresko des Künstlers Sepp Mayrhuber, das die Verklärung Christi darstellt. Auch die geschnitzten Kreuzwegstationen unter der Empore, geschaffen von Franz Barwig dem Jüngeren, verleihen der Kirche eine besondere künstlerische Note"}, {"kategorie": "", "text": "In der Kirche befinden sich außerdem Reliquien der heiligen Märtyrer Clemens und Vincentia."}]'::jsonb, ''),
  ('hiitzinga-hauptschdrossn', 'Hiitzinga Hauptschdrossn', '', '', '', '', 'Hietzinger Hauptstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), welche die ehemaligen Vororte [[Hietzing]], [[Unter-St]].-Veit und [[Ober-St]].-Veit miteinander verbindet\""}, {"kategorie": "", "text": "Diese Vororte wurden im Rahmen der Wiener Stadterweiterung von 1890/1892 in die Stadt Wien eingemeindet. Am 10. Juli 1894 beschloss der Wiener Stadtrat, der Straße den Namen Hietzinger Hauptstraße zu geben, um den historischen Vorortnamen Hietzing zu bewahren"}, {"kategorie": "", "text": "Besonders zwischen 1900 und 1910 entstand entlang der Straße eine Vielzahl repräsentativer Gründerzeitvillen und mehrgeschossiger Mietshäuser, die bis heute das Bild der Straße prägen. Diese Häuser sind typischerweise viergeschossig und zeichnen sich durch großzügig dimensionierte Wohnungen sowie Geschäftsflächen im Souterrain aus"}, {"kategorie": "", "text": "Die Fassaden der Gebäude sind reich verziert und weisen historische sowie teils secessionistische Elemente auf, die den gehobenen Charakter der Straße unterstreichen. Ein besonders markanter Bereich befindet sich stadtauswärts zwischen der Mantlergasse und der Schrutkagasse, wo eine durchgehende Verbauung auf der linken Seite besteht, während auf der rechten Seite einige freistehende Gebäude zu finden sind. Die Straße wurde zudem als Allee angelegt, deren erhaltene Bäume bis heute das Straßenbild verschönern und zum ruhigen, gehobenen Flair der Umgebung beitragen"}, {"kategorie": "", "text": "Die Hietzinger Hauptstraße hat auch eine kulturelle Bedeutung, da sie mit dem Leben des berühmten Malers Egon Schiele verbunden ist. Schiele lebte und arbeitete einige Jahre in Hietzing. Er starb im Haus Hietzinger Hauptstraße 114, eine Gedenktafel erinnert an diese historische Tatsache. Sein Atelier befand sich im letzten Stock des gegenüberliegenden Hauses (Hietzinger Hauptstraße 101), wo er zwischen 1912 und 1918 tätig war. Heute erinnert das Bezirksmuseum Hietzing an den Künstler, indem es Bilder und Erinnerungsstücke von ihm ausstellt."}]'::jsonb, ''),
  ('schloss-laudon', 'Schloss Laudon', '', '', '', '', 'Schloss Laudon', '[{"kategorie": "allg.", "text": "\"barockes Wasserschloss im 14. Wiener Gemeindebezirk ([[Penzing]]) im Stadtteil [[Hadersdorf]] (auch bekannt als Schloss Hadersdorf)\""}, {"kategorie": "", "text": "Es wurde ursprünglich im Mittelalter als Wehranlage errichtet, erstmals um 1130 urkundlich erwähnt. Nach mehrfachen Besitzerwechseln und Zerstörungen, insbesondere während der [[Ersten]] Türkenbelagerung 1529, wurde das Schloss im 17. Jahrhundert wiederaufgebaut und von Andreas Schellerer als barockes Wasserschloss neu gestaltet"}, {"kategorie": "", "text": "Seine heutige Gestalt erhielt das Schloss 1744. Feldmarschall Ernst Gideon von Laudon, ein berühmter österreichischer Militärführer, erwarb das Schloss 1776 und wohnte dort bis zu seinem Tod 1790. Es blieb bis 1925 im Besitz der Familie Laudon"}, {"kategorie": "", "text": "Das Schloss wurde später von verschiedenen Besitzern genutzt, darunter die Erzdiözese Wien und die Republik Österreich, die es heute als Standort für die Verwaltungsakademie des Bundes nutzt"}, {"kategorie": "", "text": "Der Schlosspark, einst prächtig von Laudon selbst gestaltet, hat nur noch teilweise Bestand, mit einigen erhaltenen Skulpturen und Denkmälern. Bemerkenswert ist auch das Grabmal von Feldmarschall Laudon, das er selbst im „Türkischen Gärtchen“ errichten ließ. Das Schloss ist heute nicht öffentlich zugänglich."}]'::jsonb, ''),
  ('wossatuam-favoritn', 'Wossatuam Favoritn', '', '', '', '', 'Wasserturm Favoriten', '[{"kategorie": "allg.", "text": "67 Meter hoher, historischer Wasserturm im 10. Wiener Gemeindebezirk ([[Favoriten]]), gelegen in der Windtenstraße (auch bekannt als Wasserturm am Wienerberg)"}, {"kategorie": "", "text": "Er wurde zwischen 1898 und 1899 nach Plänen des Stadtbauamts unter der Leitung von Franz Borkowitz als Teil der Ersten Hochquellenwasserleitung errichtet, um die höher gelegenen Gebiete der Bezirke Favoriten und Meidling mit Trinkwasser zu versorgen"}, {"kategorie": "", "text": "Der Wasserturm ist ein markantes Wahrzeichen von Favoriten und wurde im Stil des romantischen Burgenstils aus Steinquadermauerwerk erbaut"}, {"kategorie": "", "text": "Der Wasserturm war Teil eines größeren Gebäudekomplexes, der auch ein Wasserreservoir, ein Maschinenhaus und Nebengebäude umfasste. Diese Anlage diente der Wasserversorgung der rasch wachsenden Wiener Bevölkerung, bis der Betrieb 1910 nach der Inbetriebnahme der Zweiten Hochquellenwasserleitung schrittweise eingestellt wurde. 1956 wurde der Wasserturm endgültig aus dem Wasserversorgungssystem genommen"}, {"kategorie": "", "text": "Zwischen 1988 und 1990 wurde der Turm aufwendig saniert und ist heute ein denkmalgeschütztes Bauwerk, das nicht mehr zur Wasserversorgung genutzt wird. Er dient nun als Ausstellungs- und Veranstaltungsort und bietet aufgrund seiner Höhe einen weiten Ausblick auf Wien"}, {"kategorie": "", "text": "Der Wasserturm ist ein bemerkenswertes Beispiel für die monumentale Architektur industrieller Bauten des 19. Jahrhunderts in Wien und zählt zu den bekanntesten Wahrzeichen des Bezirks Favoriten."}]'::jsonb, ''),
  ('dominikanerinnenkonvent-hacking', 'Dominikanerinnenkonvent Hacking', '', '', '', '', 'Dominikanerinnenkonvent Hacking', '[{"kategorie": "allg.", "text": "römisch-katholisches Kloster  in der [[Schloßberggasse]] 17 im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Es wurde im Jahr 1870 von Friederike Fürstin Auersperg gegründet, die nach ihrem Eintritt ins Dominikanerinnenkloster in Augsburg 1869 als Schwester Maria Raimunda nach Wien zurückkehrte. Auf den 1869 erworbenen Grundstücken in Hacking ließ sie die Wiener Niederlassung der Dominikanerinnen errichten, wobei das Klostergebäude im Jahr 1872 fertiggestellt wurde"}, {"kategorie": "", "text": "Der Konvent begann bereits 1873 mit dem Unterricht in einer Volksschule, die 1874 das Öffentlichkeitsrecht erhielt. Ein neues Schulgebäude wurde zwischen 1896 und 1904 errichtet"}, {"kategorie": "", "text": "In den Jahren 1964 bis 1966 wurde das Kloster durch einen modernen Internatskomplex im Collegesystem erweitert, der Platz für 100 Mädchen bietet. Diese Erweiterung wurde vom bekannten österreichischen Architekten Gustav Peichl entworfen und umfasst fünf Wohnhäuser, einen Schultrakt mit Turn- und Festsaal, einen Speisesaal und eine Küche"}, {"kategorie": "", "text": "Die Dominikanerinnen von Hacking betreiben mehrere Bildungseinrichtungen: einen Kindergarten, eine Volks- und Hauptschule, ein Realgymnasium für Mädchen (gegründet 1933), ein Gymnasium sowie eine Fachschule für Wirtschaftliche Frauenberufe. Diese Einrichtungen sind für ihre hohe Qualität bekannt und bieten eine breite Bildung für junge Frauen in Wien."}]'::jsonb, ''),
  ('schbeisinga-schdrossn', 'Schbeisinga Schdrossn', '', '', '', '', 'Speisinger Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsachse im 13. und 23. Wiener Gemeindebezirk ([[Hietzing]] und [[Liesing]]), die den Stadtteil [[Speising]] durchquert\""}, {"kategorie": "", "text": "Sie verbindet den Bezirk mit anderen Teilen Wiens und ist eine der zentralen Straßen in diesem Gebiet. Die Speisinger Straße ist 2,6 Kilometer lang, beginnt am Bahnübergang bei der Schnellbahnstation Speising und endet beim [[Maurer]] Hauptplatz in [[Liesing]].  3. Zu den wichtigsten Einrichtungen entlang der Speisinger Straße gehört das Orthopädische Spital Speising"}, {"kategorie": "", "text": "Heute ist die Speisinger Straßegeprägt von einer Mischung aus Wohngebieten, Geschäften und medizinischen Einrichtungen. Sie hat sich im Laufe der Zeit zu einer lebendigen und wichtigen Verkehrsader in Hietzing entwickelt"}, {"kategorie": "", "text": "Historisch war sie ein Teil des ehemaligen Bauerndorfs Speising, das 1892 nach Wien eingemeindet wurde. Heute spiegelt die Straße sowohl die Vergangenheit als auch die moderne Entwicklung des Bezirks wider"}, {"kategorie": "", "text": "Entlang der Speisinger Straße befinden sich auch zahlreiche [[Gründerzeithäuser]]. Trotz moderner Neubauten haben viele von ihnen bis heute ihren historischen Charme bewahrt und tragen zur eleganten Atmosphäre des Bezirks Hietzing bei."}]'::jsonb, ''),
  ('schoenbrunna-schlosspark', 'Schönbrunna Schlosspark', '', '', '', '', 'Schönbrunner Schlosspark', '[{"kategorie": "", "text": "Der Schönbrunner Schlosspark liegt im 13. Wiener Gemeindebezirk ([[Hietzing]]) und umgibt das [[Schloss]] Schönbrunn"}, {"kategorie": "", "text": "Der Park wurde um 1705/1706 von dem Gartenarchitekten Jean Trehet angelegt. Im Laufe des 18. Jahrhunderts wurde der Park kontinuierlich erweitert und umgestaltet, unter anderem durch den Entwurf des Kammer- und Kronprinzengartens um 1750 durch Jean Nicolas Jadot de Ville-Issey und eine größere Umgestaltung um 1765 nach Plänen von Johann Ferdinand Hetzendorf von Hohenberg und Adrian van Steckhoven"}, {"kategorie": "", "text": "Wichtige  Elemente des Schönbrunner Schlossparks sind: (i) das Gartenparterre: Das Zentrum des Schlossparks ist das Blumenparterre, um das herum 41 Statuen angeordnet sind. Diese Statuen, die nach einer Ausschreibung hauptsächlich von Wilhelm Beyer geschaffen wurden, stellen verschiedene mythologische und historische Figuren dar;  (ii) Botanischer Garten: Dieser wurde 1848 von Heinrich Schott im äußersten Westen des Schlossparks angelegt und öffentlich zugänglich gemacht. Hier befinden sich Denkmäler, unter anderem das für [[Franz]] I., geschaffen von Balthasar Ferdinand Moll, und ein Modell des Josephsdenkmals von Franz Anton von Zauner;  (iii) Fasangarten: Im südlichen Teil des Parks befindet sich der [[Fasangarten]], der früher zu Jagdzwecken genutzt wurde;  (iv) [[Gloriette]]: Ein beeindruckendes Bauwerk, das auf einem Hügel über dem Schloss thront und einen Panoramablick über Wien bietet;  (v) Menagerie: Der [[Tiergarten]] Schönbrunn, der älteste Zoo der Welt, befindet sich ebenfalls im Park und wurde ursprünglich als kaiserliche Menagerie angelegt;  (vi) [[Neptunbrunnen]]: Dieser imposante Brunnen wurde 1780 von Franz Anton Zauner und Wilhelm Beyer errichtet und ist ein zentrales Kunstwerk im Park;  (vii) Kaskade mit Obelisk: Der Obelisk, errichtet 1777 von Johann Ferdinand Hetzendorf von Hohenberg, steht auf Schildkröten und ist mit Inschriften verziert, die Szenen aus der Geschichte des [[Hauses]] Habsburg darstellen. Die Grotte unter dem Obelisk wird Sibyllengrotte genannt;  (viii) Römische Ruine: Eine romantische Ruinenanlage, die 1778 nach einem Entwurf von Hetzendorf von Hohenberg gebaut wurde. Sie stellt einen halb versunkenen Palast dar und ist ein bedeutendes Beispiel barocker Gartenarchitektur;  (ix) Schöner Brunnen: Der Namensgeber des Schlosses, der Schöne Brunnen, ist mit einer Statue der römischen Nymphe Egeria geschmückt, die aus einem steinernen Gefäß Wasser spendet, sowie (x) Tiroler Garten: Erzherzog Johann ließ diesen Garten um 1800 als Alpengarten mit zwei Tirolerhäusern anlegen. Heute beherbergt der Garten ein Restaurant und eine Jausenstation"}, {"kategorie": "", "text": "Im Jahr 2003 wurden die bis zu neun Meter hohen Hecken entlang des Gartenparterres abgeholzt und durch Hainbuchen ersetzt, die sich an der Barockgestaltung von 1780 orientieren. Diese Restaurierung führte dazu, dass die Statuen im Gartenparterre wieder besser sichtbar wurden. Der Barockpark von Schönbrunn ist nach dem [[Augarten]] und dem [[Belvederegarten]] der drittälteste Barockgarten Wiens."}]'::jsonb, ''),
  ('eduard-popp-hof', 'Eduard-Popp-Hof', '', '', '', '', 'Eduard-Popp-Hof', '[{"kategorie": "allg.", "text": "\"kommunale Wohnhausanlage im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Bezirksteil [[Speising]], die in den Jahren 1931-1933 im Rahmen des städtischen Wohnbauprogramms errichtet wurde. Die Anlage wurde in einer Zeit gebaut, in der die Stadt Wien durch die wirtschaftliche Krise der 1930er-Jahre gezwungen war, den Wohnungsbau stark einzuschränken. Um dennoch Wohnraum und Arbeitsplätze für die arbeitslose Bevölkerung zu schaffen, entwickelte die Stadt sogenannte \"Erwerbslosensiedlungen\" am Stadtrand, wie diese in Hietzing"}, {"kategorie": "", "text": "Die Anlage liegt auf einem dreieckigen Grundstück, das von Straßen umgeben ist, und besteht aus vier Randbebauungen, die einen parkähnlichen Innenhof umschließen. Die Gebäude sind in zwei bis vier Geschossen angelegt, wobei die Stiegenhäuser durch kubische Bauteile hervorgehoben werden, was der Anlage einen unverwechselbaren, modernen Ausdruck verleiht. Besonders markant sind die konvexen Stiegenhausachsen, die sich aus den Hauswänden herausschwingen und den Gebäuden eine dynamische Form geben."}, {"kategorie": "", "text": "Die Anlage ist nach dem sozialdemokratischen Politiker Eduard Popp (1916-2001) benannt, der sich in der Arbeiterbewegung engagierte und eine bedeutende Rolle in der politischen Entwicklung Wiens spielte. Popp war in der Gewerkschaft Öffentlicher Dienst aktiv und bekleidete mehrere politische Ämter in Hietzing, darunter Bezirksrat, Bezirksvorsteher-Stellvertreter und schließlich Bezirksvorsteher"}, {"kategorie": "", "text": "Der Architekt des Eduard-Popp-Hofs war Viktor Reiter (1894-1973), ein Schüler von Leopold Bauer und Franz Krauß an der Akademie der bildenden Künste Wien. Reiter entwarf in den 1930er-Jahren mehrere Wohnhausanlagen für die [[Gemeinde]] Wien, darunter auch andere Projekte in Hietzing, wie die Wohnanlagen an der [[Speisinger]] Straße."}]'::jsonb, ''),
  ('atzgasduafa-pfoakiachn', 'Atzgasduafa Pfoakiachn', '', '', '', '', 'Atzgersdorfer Pfarrkirche', '[{"kategorie": "", "text": "Die ursprüngliche Katharinenkirche war eine spätgotische Wehrkirche mit einem Ostturm und wurde um 1300 erbaut. Diese Kirche war von einem Friedhof umgeben, der bis 1780 in Gebrauch war"}, {"kategorie": "", "text": "Die heutige Kirche entstand zwischen 1781 und 1783 unter der Schirmherrschaft von Fürsterzbischof Kardinal Christoph Anton Migazzi. Der Grundstein wurde 1781 gelegt, und die Weihe erfolgte 1782, während die Bauarbeiten 1783 abgeschlossen wurden"}, {"kategorie": "", "text": "Die heutige Atzgersdorfer Kirche besitzt ein flachgedecktes Langhaus mit jeweils vier Seitenkapellen und einem eingezogenen, rechteckigen Chor, an den ein Turm anschließt. Die Innenausstattung ist klassizistisch geprägt. Der Hochaltar stammt aus der Bauzeit der Kirche, und die beiden Seitenaltarbilder wurden 1785 von Hubert Maurer gemalt"}, {"kategorie": "", "text": "Besonders bemerkenswert ist das sogenannte \"Fieber- oder Türkenkreuz\", das 1761 in die alte Kirche übertragen wurde und im 18. Jahrhundert Ziel von Wallfahrten war"}, {"kategorie": "", "text": "Die Orgel stammt ursprünglich aus der Leonhardikapelle in Perchtoldsdorf und wurde 1784 in die Atzgersdorfer Kirche eingebaut"}, {"kategorie": "", "text": "Ein weiteres bedeutendes Kunstwerk ist der Taufstein, der vom Heiligenkreuzer Abt Gerard Weixelberger (1660-1728) noch der alten Kirche gestiftet wurde. Das Gemälde \"Christus wandelt auf dem See Genezareth\" von Adam Brenner (1833) ist ein weiteres künstlerisches Highlight der Kirche"}, {"kategorie": "", "text": "Nach dem Verlust der Glocken im Ersten Weltkrieg wurden 1920 vier neue Glocken angeschafft. Die Schäden, die das Dach und der Kirchturm während des Zweiten Weltkriegs erlitten hatten, wurden 1948 behoben"}, {"kategorie": "", "text": "Der Teil des Liesinger Bezirkswappens, der Atzgersdorf repräsentiert, zeigt die heilige Katharina mit einem Palmzweig und einem Schwert auf einer grünen Wiese, was einen direkten Bezug zur Pfarrkirche Heilige Katharina herstellt."}]'::jsonb, ''),
  ('schdodtpark-atzgasduaf', 'Schdodtpark Atzgasduaf', '', '', '', '', 'Stadtpark Atzgersdorf', '[{"kategorie": "allg.", "text": "\"neue Parkanlage im 23. Wiener Gemeindebezirk ([[Liesing]]), im Stadtteil [[Atzgersdorf]] an der [[Breitenfurter]] Straße 267\""}, {"kategorie": "", "text": "Der Park wurde 2023 eröffnet und entstand auf dem Gelände des ehemaligen Campingplatzes Wien Süd, der einige Jahre zuvor aufgegeben wurde. Mit einer Fläche von etwa 2,7 Hektar bietet der Park nun eine grüne Oase in Atzgersdorf"}, {"kategorie": "", "text": "Der Park hat eine interessante historische Verbindung: In der unmittelbaren Nachbarschaft befand sich im 19. Jahrhundert eine Textildruckerei, später umgewandelt in eine Lederfabrik von Gustav Pollak, einem böhmisch-jüdischen Industriellen. Auf diesem Gelände steht heute ein Seniorenheim, das Haus am Mühlengrund"}, {"kategorie": "", "text": "Reste der ursprünglichen Villa von Pollak, die um 1900 vom Architekten Josef Hoffmann gestaltet wurde, sind noch im Park zu finden, darunter ein kleiner Mauerrest und ein Brunnenfragment. Vier besondere Bäume – eine Eibe, eine Esche, eine Schwarzkiefer und eine Zerreiche – sind als Naturdenkmäler geschützt und erinnern an die Geschichte des Gartens"}, {"kategorie": "", "text": "Am Rand des Parks steht eine kleine Kapelle mit einem dreieckigen Grundriss, die eine Statue des heiligen Johannes Nepomuk beherbergt. Die Kapelle, die nach 1809 errichtet wurde, steht heute unter Denkmalschutz. Sie wurde 1963 versetzt, da sie zuvor an einer anderen Stelle ein Verkehrshindernis darstellte"}, {"kategorie": "", "text": "Die Kapelle hat eine bewegte Geschichte: Sie wurde vom Vater der Theresia Kandl als Sühne gestiftet. Theresia hatte ihren Ehemann mit einer Hacke erschlagen und wurde dafür 1809 am [[Wienerberg]] hingerichtet. Sie war die einzige Frau, die an diesem Ort erhängt wurde. Ihre Hinrichtung zog viele Schaulustige an, nicht zuletzt, weil sie jung und attraktiv war."}]'::jsonb, ''),
  ('aum-rosnbeag', 'Aum Rosnbeag', '', '', '', '', 'Am Rosenberg', '[{"kategorie": "allg.", "text": "\"Straße im 13. und 23. Wiener Gemeindebezirk ([[Hietzing]] und [[Liesing]]), welche die Stadtteile Speising und Mauer miteinander verbindet und nach einem alten Flurnamen (Rosenberg) benannt ist\""}, {"kategorie": "", "text": "Früher war Rosenberg bis 1891 sogar eine eigene Katastralgemeinde im 13. Bezirk. Nach diesem Flurnamen wurden die Straßen Am Rosenberg und Rosenberggasse benannt"}, {"kategorie": "", "text": "Auf dem Gelände des heutigen Neurologischen Krankenhauses"}, {"kategorie": "", "text": "Die offizielle Benennung des Gebiets als \"Am Rosenberg\" erfolgte am 2. Juni 1965 durch den Gemeinderatsausschuss für Kultur, um die historische Bedeutung des Namens zu bewahren"}, {"kategorie": "", "text": "Obwohl die landwirtschaftliche Nutzung des Gebiets der Vergangenheit angehört, erinnert der historische Flurname noch an die ländliche Geschichte des Gebiets. Heute ist die Straße Am Rosenberg eine gefragte Wohngegend, die wegen ihrer Nähe zu den Grünflächen des Wienerwaldes und des Lainzer Tiergartens beliebt ist."}]'::jsonb, ''),
  ('helene-potetz-hof', 'Helene-Potetz-Hof', '', '', '', '', 'Helene-Potetz-Hof', '[{"kategorie": "allg.", "text": "\"städtische Wohnhausanlage im 12. Wiener Gemeindebezirk ([[Meidling]]) an der [[Rosenhügelstraße]] 35 und Endergasse 2 gelegen\""}, {"kategorie": "", "text": "Die Anlage umfasst 45 Wohnungen und wurde zwischen 1984 und 1987 von den Architekten Edith Lassmann und Manfred Rapf errichtet"}, {"kategorie": "", "text": "Der Wohnhof ist nach Helene Potetz benannt, einer bedeutenden Wiener Politikerin und Widerstandskämpferin. Potetz war Mitglied der Revolutionären Sozialisten und wurde sowohl während des Ständestaates als auch während der Zeit des Nationalsozialismus verfolgt. Nach dem Zweiten Weltkrieg war sie ab 1945 Mitglied des Wiener Gemeinderats, von 1949 bis 1967 dessen Vorsitzende und von 1959 bis 1967 die dritte Landtagspräsidentin von Wien"}, {"kategorie": "", "text": "Der Helene-Potetz-Hof trägt somit den Namen einer Frau, die sich durch ihr Engagement für soziale Gerechtigkeit und ihre politische Arbeit in der Nachkriegszeit einen bedeutenden Platz in der Wiener Geschichte erarbeitet hat"}]'::jsonb, ''),
  ('schloss-rodaun', 'Schloss Rodaun', '', '', '', '', 'Schloss Rodaun', '[{"kategorie": "", "text": "Das Schloss wurde erstmals 1405 urkundlich erwähnt, wobei der Ursprung des Gebäudes vermutlich bis in die Zeit der [[Babenberger]] (vor 1246) zurückreicht. Das Schloss war ein bedeutendes Zentrum des Protestantismus während der Reformation unter den Freiherren von Landau im 16. Jahrhundert"}, {"kategorie": "", "text": "Das heutige dreigeschossige klassizistische Bauwerk stammt größtenteils aus dem späten 18. Jahrhundert, nachdem es im Laufe der Jahrhunderte mehrfach umgebaut und erweitert wurde. Zu den historischen Merkmalen gehören ein Renaissancetor (1578) und die Philippus- und Jakobus-Kapelle, die auf das 18. Jahrhundert zurückgeht"}, {"kategorie": "", "text": "Das Schloss war während der [[Türkenbelagerungen]] Wiens relativ unbeschädigt geblieben und spielte eine wichtige Rolle in der lokalen Geschichte. Seit 1898 gehört es dem katholischen Orden der Schwestern der heiligen Kindheit Jesu und Mariä"}, {"kategorie": "", "text": "Das Schloss und der dazugehörige Schlosspark werden heute vom Schulzentrum Santa Christiana genutzt, das dort seit 1902 ein Mädchenpensionat betrieb. Heute beherbergt es mehrere Schulstufen, darunter eine Volksschule, Kooperative Mittelschule und Fachschule."}]'::jsonb, ''),
  ('beagkiachn-rodaun', 'Beagkiachn Rodaun', '', '', '', '', 'Bergkirche Rodaun', '[{"kategorie": "", "text": "Sie liegt auf einer Seehöhe von 267 m auf einer Anhöhe über dem Tal des [[Liesingbachs]] und ist dem heiligen Johannes dem Täufer geweiht\""}, {"kategorie": "", "text": "Die heutige Kirche wurde zwischen 1739 und 1745 erbaut, nachdem die alte Kapelle baufällig geworden war. Der Bau wird der Schule des berühmten Barockarchitekten Johann Bernhard Fischer von Erlach zugeschrieben"}, {"kategorie": "", "text": "Die Kirche spielte historisch eine wichtige Rolle in der Zeit der Reformation, als die Herrschaft Rodaun ein Zentrum des Protestantismus war"}, {"kategorie": "", "text": "Die Kirche besitzt eine klassizistische Fassade mit Pilastern und toskanischen Kapitellen. Der Turm ist mit Steinfiguren und einem Wappen des ehemaligen Schlossherrn Johann Philipp von Rödersthal verziert. Im Inneren ist die Kirche ein Zentralbau mit einer Hängekuppel und barocken Kunstwerken, darunter ein Hochaltarbild, das die Taufe Christi darstellt"}, {"kategorie": "", "text": "Eine der ältesten Kostbarkeiten der Kirche ist eine kleine Glocke aus dem Jahr 1503, die in Italien gegossen wurde"}, {"kategorie": "", "text": "Vor der Kirche befinden sich mehrere Denkmäler, darunter eine Christusstatue (1881), ein Kriegerdenkmal von Richard Kauffungen und zwei Sandsteinstatuen aus dem 18. Jahrhundert"}, {"kategorie": "", "text": "Seit 1964 ist die Pfarre in die neue Rodauner Kirche umgezogen (Pfarrkirche Rodaun), wobei die Bergkirche ihren historischen und kulturellen Wert als Denkmal weiterhin beibehält."}]'::jsonb, ''),
  ('hofmannsthal-schloessl', 'Hofmannsthal-Schlössl', '', '', '', '', 'Hofmannsthal-Schlössl', '[{"kategorie": "allg.", "text": "\"Herrschaftshaus im 23. Wiener Gemeindebezirk ([[Liesing]]), genauer im Stadtteil [[Rodaun]], das durch seinen früheren Bewohner, den Schriftsteller Hugo von Hofmannsthal, Bekanntheit erlangt hat\""}, {"kategorie": "", "text": "Das barocke Anwesen, bestehend aus einem zweigeschossigen Herrenhaus, einem ebenfalls zweigeschossigen Nebengebäude (Stöckl) und einem großen Garten von 3.000 m², diente über die Jahrhunderte verschiedenen adeligen und bürgerlichen Familien als Wohnsitz"}, {"kategorie": "", "text": "Im Jahr 1755 wurde das Schlössl von Carolina Fürstin von Trautson erworben, die eine enge Verbindung zum Wiener Kaiserhof hatte, da sie als Erzieherin der ältesten Töchter von Kaiserin [[Maria]] Theresia wirkte. Die Fürstin besaß das Anwesen zehn Jahre lang und trug zur weiteren Entwicklung des Hauses bei"}, {"kategorie": "", "text": "Berühmtheit erlangte das Anwesen vor allem durch den österreichischen Schriftsteller Hugo von Hofmannsthal, der das Haus von 1900 bis 1929 mit seiner Familie bewohnte"}, {"kategorie": "", "text": "Das Schlössl, das damals an der Badgasse lag, diente Hofmannsthal und seiner Familie als ganzjähriger Wohnsitz, auch wenn es nur durch Holzöfen beheizt werden konnte. Nach dem Tod des Dichters blieb seine Frau Gerty dort bis 1938, als sie nach dem [[Anschluss]] Österreichs nach England fliehen musste"}, {"kategorie": "", "text": "Das Herrenhaus beeindruckt durch seine barocken Stuckdecken und die Wandmalereien im Stil von Johann Christian Brand. Im Erdgeschoss des Nebengebäudes befindet sich eine Kapelle mit einem [[Stichkappengewölbe]], die ebenfalls zur barocken Ausstattung des Hauses zählt. Eine Besonderheit ist auch die Gestaltung des Eingangsbereichs durch den berühmten Bühnenbildner Alfred Roller zu Beginn des 20. Jahrhunderts"}, {"kategorie": "", "text": "Heute befindet sich das Anwesen in Privatbesitz, bleibt jedoch als Wohnort von Hugo von Hofmannsthal und wegen seiner kunsthistorischen Bedeutung ein wichtiges kulturelles Erbe in Wien-Rodaun."}]'::jsonb, ''),
  ('rodauna-schdrossn', 'Rodauna Schdrossn', '', '', '', '', 'Rodauner Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 23. Wiener Gemeindebezirk ([[Liesing]]), die den Stadtteil [[Rodaun]] mit anderen Teilen von Wien verbindet\""}, {"kategorie": "", "text": "Sie verläuft vom Zentrum von Rodaun in Richtung [[Mauer]] und ist ein zentraler Verkehrsweg für Pendler sowie Anwohner"}, {"kategorie": "", "text": "Die Straße trägt ihren Namen nach dem Bezirksteil [[Rodaun]], der historisch bedeutsam ist und als eine der ältesten Siedlungen in der Region gilt"}, {"kategorie": "", "text": "In der Nähe der Rodauner Straße liegen Sehenswürdigkeiten wie das [[Schloss]] Rodaun und die [[Rodauner]] Bergkirche, die zu den kulturellen und historischen Wahrzeichen des Bezirks zählen."}]'::jsonb, ''),
  ('oid-ealaa', 'Oid-Ealaa', '', '', '', '', 'Alt-Erlaa', '[{"kategorie": "", "text": "Der Ortsteil entwickelte sich rund um einen mittelalterlichen Herrschaftssitz, der seit dem 17. Jahrhundert bezeugt ist und später in das barocke [[Erlaaer]] Schloss überging"}, {"kategorie": "", "text": "Das Schloss, das Ende des 18. Jahrhunderts unter der Grundherrschaft von Fürst Georg Adam von Starhemberg erbaut wurde, bildet bis heute einen markanten Teil des historischen Zentrums von Alt-Erlaa. In unmittelbarer Nähe befindet sich die [[Kirche]] Alterlaa, die ebenfalls einen wichtigen Bezugspunkt der örtlichen Geschichte darstellt"}, {"kategorie": "", "text": "In der modernen Zeit ist Alt-Erlaa vor allem durch den [[Wohnpark]] Alterlaa bekannt, eine der markantesten Wohnanlagen Wiens, die zwischen 1973 und 1985 errichtet wurde. Diese großen Wohnbauten prägen das heutige Erscheinungsbild von Alt-Erlaa und verbinden die historische Bedeutung des Gebiets mit seiner modernen Entwicklung als urbanes Wohnviertel."}]'::jsonb, ''),
  ('schloss-oid-ealaa', 'Schloss Oid-Ealaa', '', '', '', '', 'Schloss Alt-Erlaa', '[{"kategorie": "", "text": "Im 17. Jahrhundert wurde es zu einem vierflügeligen Schloss ausgebaut, wie auf einem Stich von Georg Matthäus Vischer aus dem Jahr 1672 zu sehen ist"}, {"kategorie": "", "text": "Unter Georg Adam von Starhemberg, der das Schloss 1765 erwarb, wurde es von 1766 bis 1770 im spätbarock-klassizistischen Stil, vermutlich nach Plänen des Hofarchitekten Nikolaus Pacassi, umgebaut. Zu dieser Zeit wurde auch der weitläufige Schlosspark angelegt"}, {"kategorie": "", "text": "Das Schloss spielte in der Geschichte eine bedeutende Rolle: Napoleons Truppen waren 1805 und 1809 dort einquartiert, und Jerome Bonaparte, der Bruder Napoleons, erwarb es 1817 vorübergehend"}, {"kategorie": "", "text": "Im 19. Jahrhundert ließ Freiherr Peter von Braun den Schlosspark in einen englischen Landschaftsgarten mit Kaskaden, Tempeln und künstlichen Ruinen umwandeln, der zu einer Sehenswürdigkeit wurde"}, {"kategorie": "", "text": "Heute besteht das Schloss aus einem zweigeschossigen Hauptgebäude mit Walmdach und zwei Seitenflügeln, die einen Ehrenhof umschließen. Die Architektur des Schlosses zeichnet sich durch erhaltene [[Kreuzgratgewölbe]] aus dem 16./17. Jahrhundert und Holzvertäfelungen mit Rocaille-Schnitzereien aus dem Jahr 1770 aus"}, {"kategorie": "", "text": "Das Schloss befindet sich an der Erlaaer Straße 54, in der Nähe des [[Wohnparks]] Alt-Erlaa, und ist bis heute im Besitz der Familie Brenner von Felsach, die das Schloss 1918 erwarb."}]'::jsonb, ''),
  ('oid-ealaara-schlosspark', 'Oid-Ealaara Schlosspark', '', '', '', '', 'Alterlaaer Schlosspark', '[{"kategorie": "", "text": "Der Schlosspark wurde um 1770 als englischer Landschaftsgarten angelegt und zählt zu den ältesten Parkanlagen dieser Art in Wien. Trotz einer Umgestaltung im 19. Jahrhundert blieb seine ursprüngliche Struktur weitgehend erhalten"}, {"kategorie": "", "text": "Im Park finden sich künstlich angelegte Wasserläufe mit Kaskaden (stufenförmigen Wasserfällen), eine Grotte, sowie eine künstliche Ruine, ein Rundtempel, mehrere Steinbänke und die Reste von Brücken, die ebenfalls aus dem 18. Jahrhundert stammen. Diese romantischen Elemente sind typisch für englische Landschaftsgärten jener Zeit"}, {"kategorie": "", "text": "Ein besonderes Merkmal des Parks ist das „vergessene Denkmal“ an der [[Kugelmanngasse]], benannt nach einer steinernen Statue des Atlas, die die Himmelskugel trägt und volkstümlich als „Kugelmann“ bekannt ist."}]'::jsonb, ''),
  ('pfoakiachn-oid-ealaa', 'Pfoakiachn Oid-Ealaa', '', '', '', '', 'Pfarrkirche Alterlaa', '[{"kategorie": "", "text": "Sie wurde ursprünglich im Rahmen der Planung des [[Wohnparks]] Alt-Erlaa (erbaut ab 1973) vorgesehen, jedoch zunächst nicht realisiert. Stattdessen wurden ab Ende 1980 Gottesdienste im ersten Stock des Kaufparks abgehalten"}, {"kategorie": "", "text": "Die Kirche, entworfen von Thomas Reinthaller, wurde schließlich am 10. September 1983 geweiht. Zu den bedeutendsten Kunstwerken in der Kirche zählt das Kreuz, geschaffen von Oskar Höfinger (1983), das als eines seiner wichtigsten Werke gilt"}, {"kategorie": "", "text": "Eine weitere Besonderheit ist eine griechische Ikone, die ein Geschenk des ehemaligen österreichischen Bundespräsidenten Dr. Rudolf Kirchschläger ist."}]'::jsonb, ''),
  ('pfoakiachn-nei-ealaa', 'Pfoakiachn Nei-Ealaa', '', '', '', '', 'Pfarrkirche Neu-Erlaa', '[{"kategorie": "", "text": "Die Kirche wurde in den Jahren 1960-1962 nach Plänen des Architekten Herbert Schmid erbaut und am 23. September 1962 von Erzbischof-Koadjutor Franz Jachym geweiht"}, {"kategorie": "", "text": "Sie ging aus einer Expositur der Pfarre [[Atzgersdorf]] hervor, die bereits 1954 eingerichtet wurde und von den Salesianern Don Boscos betreut wurde"}, {"kategorie": "", "text": "Die Ausstattung der Kirche umfasst Kunstwerke wie den Kreuzweg aus Glockenbronze und ein Außenrelief aus Granitguss, geschaffen von Bohdan Zarovsky. Das Kreuz und die Madonna stammen vom Zillertaler Bildhauer Albin Moroder, während der Tabernakel, der Taufstein und das Vortragskreuz von Fred Gillesberger gestaltet wurden"}, {"kategorie": "", "text": "Seit dem 1. Jänner 1975 ist die Kirche eine eigenständige Pfarre."}]'::jsonb, ''),
  ('nei-ealaa', 'Nei-Ealaa', '', '', '', '', 'Neu-Erlaa', '[{"kategorie": "allg.", "text": "\"Stadtteil im 23. Wiener Gemeindebezirk ([[Liesing]]), der ursprünglich als Erweiterung von [[Alt-Erlaa]] entstand\""}, {"kategorie": "", "text": "Der Ortsteil wurde im 19. Jahrhundert entlang der Verbindung zur [[Triester]] Straße angelegt, um dem wachsenden Bedarf an Wohnraum gerecht zu werden. Er entwickelte sich besonders stark zwischen 1860 und 1873 und wuchs schließlich mit Alt-Erlaa zusammen"}, {"kategorie": "", "text": "Historisch war Neuerlaa landwirtschaftlich geprägt, erlebte jedoch durch die Industrialisierung und den Bevölkerungszuwachs einen Wandel. Neuerlaa wurde 1938 im Rahmen der Eingemeindung nach Wien Teil des neugeschaffenen 25. Bezirks (später der 23. Bezirk)"}, {"kategorie": "", "text": "Heute ist Neuerlaa ein verstädtertes Wohngebiet mit modernen Einrichtungen und Wohnbauprojekten"}, {"kategorie": "", "text": "Eine zentrale Sehenswürdigkeit in Neuerlaa ist die Pfarrkirche Neu-Erlaa (\"Heiliger Dominikus Savio\"), die in den Jahren 1960-1962 erbaut und zum spirituellen Zentrum des Stadtteils wurde."}]'::jsonb, ''),
  ('ealaara-schdrossn', 'Ealaara Schdrossn', '', '', '', '', 'Erlaaer Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 23. Wiener Gemeindebezirk ([[Liesing]]), welche die Bezirksteile [[Atzgersdorf]] und [[Erlaa]] miteinander verbindet\""}, {"kategorie": "", "text": "Sie wurde am 7. Dezember 1955 vom Gemeinderatsausschuss für Kultur benannt, um den historischen Ortsnamen Erlaa zu bewahren und seine Bedeutung für die Region hervorzuheben"}, {"kategorie": "", "text": "Die Erlaaer Straße verläuft durch die alten Ortszentren von [[Alt-Erlaa]] und [[Neu-Erlaa]], die heute stark miteinander verwachsen sind"}, {"kategorie": "", "text": "Entlang der Erlaaer Straße finden sich zahlreiche Wohnhäuser, Geschäfte und öffentliche Einrichtungen, die den Charakter der Umgebung prägen. Trotz der Verstädterung der Umgebung trägt die Erlaaer Straße dazu bei, die historische Identität der alten Ortsgemeinde [[Erlaa]] im Stadtbild zu bewahren und weiterzuführen"}, {"kategorie": "", "text": "Die Straße ist nicht nur eine zentrale Verkehrsverbindung für Pendler und Anwohner, sondern auch eine Achse, die zu wichtigen historischen und modernen Sehenswürdigkeiten führt, wie etwa dem barocken [[Schloss]] Alterlaa und dem berühmten [[Wohnpark]] Alt-Erlaa."}]'::jsonb, ''),
  ('rosskastaniin-allee', 'Rosskastaniin-Allee', '', '', '', '', 'Rosskastanien-Allee', '[{"kategorie": "allg.", "text": "\"historisch bedeutende Allee in der heutigen [[Gregorygasse]] 23. Wiener Gemeindebezirk ([[Liesing]]), genauer im Stadtteil Alt-Erlaa\""}, {"kategorie": "", "text": "Die Allee (früher \"Schlossallee\") führt zum [[Schloss]] Alterlaa, ist in Richtung des kaiserlichen [[Schlosses]] Schönbrunn ausgerichtet und steht unter Naturschutz"}, {"kategorie": "", "text": "Sie besteht aus alten, eindrucksvollen Rosskastanienbäumen, die ein prägendes landschaftliches und historisches Element der Gegend darstellen"}, {"kategorie": "", "text": "Die Rosskastanienallee wurde ursprünglich als repräsentativer Zugang zum [[Schloss]] Alterlaa angelegt und verbindet das Anwesen mit den umliegenden Gebieten"}, {"kategorie": "", "text": "Die heute als [[Gregorygasse]] bekannte Straße bewahrt durch die Allee das historische Ambiente und trägt zum Erhalt des kulturellen Erbes von [[Erlaa]] bei."}]'::jsonb, ''),
  ('inzasduafa-kiachnplotz', 'Inzasduafa Kiachnplotz', '', '', '', '', 'Inzersdorfer Kirchenplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 23. Wiener Gemeindebezirk ([[Liesing]]) im Stadtteil Inzersdorf\""}, {"kategorie": "", "text": "Der Platz wurde am 6. Mai 1947 vom Gemeinderatsausschuss für Kultur nach der auf dem Platz befindlichen \"Kirche St. Nikolaus\" ([[Pfarrkirche]] Inzersdorf) benannt"}, {"kategorie": "", "text": "Der Platz bildet das historische Zentrum von Inzersdorf und ist von großer kultureller Bedeutung. Während der Zeit des Nationalsozialismus wurde er ab 1938 in Adolf-Hitler-Platz umbenannt, bevor er nach dem [[Zweiten]] Weltkrieg seinen heutigen Namen erhielt"}, {"kategorie": "", "text": "Heute ist der Kirchenplatz ist ein zentraler Treffpunkt in Inzersdorf, umgeben von historischen Gebäuden und in direkter Nähe zur [[Pfarrkirche]] St. Nikolaus, die das geistliche und architektonische Herz des Stadtteils darstellt."}]'::jsonb, ''),
  ('grossmoakd-inzasduaf', 'Grossmoakd Inzasduaf', '', '', '', '', 'Großmarkt Inzersdorf', '[{"kategorie": "allg.", "text": "\"größter Großhandelsstandort für Lebensmittel und Blumen in Österreich, spezialisiert auf den B2B-Bereich (Business-to-Business)\""}, {"kategorie": "", "text": "Der Großmarkt liegt im [[Blumental]] in [[Inzersdorf]], einem Teil des 23. Wiener Gemeindebezirks ([[Liesing]])"}, {"kategorie": "", "text": "Der Markt wurde 1972 eröffnet, erstreckt sich über 30 Hektar und umfasst mehrere spezialisierte Bereiche, darunter eine Blumenhalle von 10.000 Quadratmetern, die für 50 % des Blumenhandels in Österreich verantwortlich ist, sowie einen Fleischgroßmarkt von 7.000 Quadratmetern"}, {"kategorie": "", "text": "Der 1972 eröffnete Großmarkt ersetzte die Obst- und Gemüsemärkte westlich des [[Naschmarkts]] (für inländische Waren) und am [[Matzleinsdorfer]] Frachtenbahnhof (für ausländische Waren) sowie den Blumengroßmarkt in der [[Phorushalle]] auf der Wieden. 2007 übersiedelte zudem der Fleischmarkt von [[Sankt]] Marx auf den Großmarkt in Wien"}, {"kategorie": "", "text": "Der Großmarkt spielt eine zentrale Rolle im österreichischen Obst- und Gemüsehandel, der dort 70 % des nationalen Gesamtumschlags ausmacht."}]'::jsonb, ''),
  ('grossgruenmoakd-inzasduaf', 'Grossgrünmoakd Inzasduaf', '', '', '', '', 'Großgrünmarkt Inzersdorf', '[{"kategorie": "allg.", "text": "\"größter Großhandelsstandort für Lebensmittel und Blumen in Österreich, spezialisiert auf den B2B-Bereich (Business-to-Business)\""}, {"kategorie": "", "text": "Der Großmarkt liegt im [[Blumental]] in [[Inzersdorf]], einem Teil des 23. Wiener Gemeindebezirks ([[Liesing]])"}, {"kategorie": "", "text": "Der Markt wurde 1972 eröffnet, erstreckt sich über 30 Hektar und umfasst mehrere spezialisierte Bereiche, darunter eine Blumenhalle von 10.000 Quadratmetern, die für 50 % des Blumenhandels in Österreich verantwortlich ist, sowie einen Fleischgroßmarkt von 7.000 Quadratmetern"}, {"kategorie": "", "text": "Der 1972 eröffnete Großmarkt ersetzte die Obst- und Gemüsemärkte westlich des [[Naschmarkts]] (für inländische Waren) und am [[Matzleinsdorfer]] Frachtenbahnhof (für ausländische Waren) sowie den Blumengroßmarkt in der [[Phorushalle]] auf der Wieden. 2007 übersiedelte zudem der Fleischmarkt von [[Sankt]] Marx auf den Großmarkt in Wien"}, {"kategorie": "", "text": "Der Großmarkt spielt eine zentrale Rolle im österreichischen Obst- und Gemüsehandel, der dort 70 % des nationalen Gesamtumschlags ausmacht."}]'::jsonb, ''),
  ('kaisa-ferdinands-wossaleitung', 'Kaisa-Ferdinands-Wossaleitung', '', '', '', '', 'Kaiser-Ferdinands-Wasserleitung', '[{"kategorie": "allg.", "text": "\"erste moderne Wasserleitung Wiens, eröffnet 1841, welche große Teile der Vorstädte mit Trinkwasser versorgte\""}, {"kategorie": "", "text": "Sie wurde nach Kaiser [[Ferdinand]] I. benannt, der 1835 seine Krönungsgeschenke, darunter 20.000 Gulden von der Stadt Wien, für den Bau der Wasserleitung zur Verfügung stellte"}, {"kategorie": "", "text": "Der Bau der Wasserleitung wurde notwendig, da die Bevölkerung Wiens in den ersten Jahrzehnten des 19. Jahrhunderts um etwa 40 Prozent zunahm und die schlechten hygienischen Zustände, besonders während der [[Choleraepidemie]] 1831/1832, die gesundheitlichen Gefahren von verunreinigtem Trinkwasser offenbarten. Viele Hausbrunnen waren durch Abwässer verschmutzt, was die Ausbreitung von Krankheiten begünstigte"}, {"kategorie": "", "text": "Die Kaiser-Ferdinands-Wasserleitung war ein wichtiger Schritt zur Verbesserung der Trinkwasserversorgung und der öffentlichen Gesundheit in Wien."}]'::jsonb, ''),
  ('pfoakiachn-inzasduaf', 'Pfoakiachn Inzasduaf', '', '', '', '', 'Pfarrkirche Inzersdorf', '[{"kategorie": "", "text": "Sie ist eine der ältesten Kirchen in Wien und dem Heiligen Nikolaus geweiht (daher auch bekannt als \"Pfarrkirche Sankt Nikolaus\")"}, {"kategorie": "", "text": "Sie wurde ursprünglich im Jahr 1217 von Ulrich von Rodaun, dem damaligen Herrscher über Inzersdorf, als unabhängige Pfarre gegründet. Die Kirche hat eine lange Geschichte von Zerstörungen und Wiederaufbauten hinter sich, vor allem durch die beiden [[Türkenbelagerungen]] Wiens (1529 und 1683) und durch Verwüstungen in den [[Napoleonischen]] Kriegen"}, {"kategorie": "", "text": "Die heutige klassizistische Kirche wurde zwischen 1817 und 1820 unter dem Schlossbesitzer Fürst Jakob a Sancto Mauro erbaut. Es handelt sich um einen Zentralbau mit gedrückter Kuppel und einem nördlich angeordneten Kirchturm, der auf italienische Vorbilder zurückgeht"}, {"kategorie": "", "text": "Die Kirche wurde mehrfach erweitert, unter anderem durch den Industriellen Alois Miesbach in den Jahren 1845/1846, der unter anderem eine Sakristei und einen Säulenportikus hinzufügen ließ"}, {"kategorie": "", "text": "Im Inneren der Kirche befinden sich mehrere Kunstwerke, darunter eine Nachbildung des berühmten Lettnerkreuzes aus dem Stephansdom (aufgestellt 1846) sowie Kirchenfenster und ein Kreuzweg, gestaltet von Anton Lehmden. An der Ostseite der Kirche befindet sich die Marienkapelle, die ursprünglich als Grabkapelle für die Familie Miesbach-Drasche diente"}, {"kategorie": "", "text": "Die Kirche wurde im Zweiten Weltkrieg schwer beschädigt, aber zwischen 1956 und 1964 wieder aufgebaut und in den Jahren 1980/1981 grundlegend renoviert. 2016 schuf Johannes Rohlf eine neue Orgel, wobei er das erhalten gebliebene alte Rückpositiv mit einbezog (Rückpositiv = kleinerer Teil der Orgel, der sich meist auf der Rückseite oder unterhalb der Hauptorgel (Hauptwerk) befindet. Es besitzt eigene Pfeifenreihen und wird oft von einem separaten Manual (Tastenreihe) gespielt, um klangliche Vielfalt zu ermöglichen)."}]'::jsonb, ''),
  ('islamischa-friidhof', 'Islamischa Friidhof', '', '', '', '', 'Islamischer Friedhof', '[{"kategorie": "allg.", "text": "\"erster islamischer Friedhof in Österreich, welcher am 3. Oktober 2008 eröffnet wurde\""}, {"kategorie": "", "text": "Der islamische Friedhof befindet sich im 23. Wiener Gemeindebezirk ([[Liesing]]), in der Großmarktstraße 2a\""}, {"kategorie": "", "text": "Die Anlage umfasst etwa 5.000 Grabstätten, die alle symmetrisch nach Mekka ausgerichtet sind, entsprechend den Bestattungsritualen des Islam"}, {"kategorie": "", "text": "Der Friedhof wurde von Herbert Schuller entworfen und ist geprägt durch eine große, moderne Aufbahrungshalle, die von einem beeindruckenden Kronleuchter beleuchtet wird. Besonders auffällig sind die 24 Suren aus dem Koran, die in Keramikflächen eingelassen sind und aus einer türkischen Stadt mit bekannter Keramiktradition stammen. Eine Gedenktafel erinnert an die erfolgreiche Zusammenarbeit zwischen der Islamischen Glaubensgemeinschaft und der Stadt Wien bei der Errichtung des Friedhofs"}, {"kategorie": "", "text": "Historisch wurden Muslime in Wien seit dem späten 19. Jahrhundert auf dem [[Zentralfriedhof]] bestattet, wo in den 1970er Jahren eine erste islamische Abteilung geschaffen wurde"}, {"kategorie": "", "text": "Aufgrund der steigenden Nachfrage nach islamischen Bestattungen nahm die Islamische Glaubensgemeinschaft in Österreich (IGGÖ) Anfang der 2000er Jahre Verhandlungen mit der Stadt Wien auf, die schließlich zur Gründung dieses eigenständigen Islamischen Friedhofs führten."}]'::jsonb, ''),
  ('gruenbeaga-schloessl', 'Grünbeaga Schlössl', '', '', '', '', 'Grünberger Schlössl', '[{"kategorie": "", "text": "Das Gebäude wurde zwischen 1720 und 1730 errichtet und zählt zu den bedeutenden barocken Landhäusern dieser Region. Es ist eines der wenigen noch erhaltenen Beispiele für die ländlichen Rückzugsorte, die wohlhabende Wiener Familien in dieser Zeit erbauen ließen"}, {"kategorie": "", "text": "Wie viele ähnliche Bauwerke diente das Grünberg-Schlössl nicht nur als Wohnhaus, sondern auch als Sommerresidenz und Erholungsort abseits des städtischen Lebens. Typisch für barocke Landhäuser dieser Epoche war eine repräsentative Bauweise, die eine Verbindung zwischen städtischem Komfort und ländlicher Idylle schuf. Diese Residenzen boten den wohlhabenden Wiener Bürgern und Adeligen nicht nur einen Platz zur Erholung, sondern auch Gelegenheit, gesellschaftliche Veranstaltungen in einer exklusiven Umgebung abzuhalten"}, {"kategorie": "", "text": "Das Grünberger Schlössl, mit seiner Lage im Süden Wiens, hat eine bewegte Geschichte hinter sich und spiegelt das architektonische und kulturelle Erbe des Barock in Wien wider. Heute steht das Gebäude unter Denkmalschutz und erinnert an die reiche Geschichte des 18. Jahrhunderts in dieser Region."}]'::jsonb, ''),
  ('maria-theresiin-schloessl', 'Maria-Theresiin-Schlössl', '', '', '', '', 'Maria-Theresien-Schlössl', '[{"kategorie": "allg.", "text": "\"beeindruckendes Beispiel eines barocken Gartenschlosses, das in der ersten Hälfte des 18. Jahrhunderts errichtet wurde\""}, {"kategorie": "", "text": "Es befindet sich in der [[Hochwassergasse]] 38 im Bezirksteil [[Inzersdorf]] im 23. Wiener Gemeindebezirk ([[Liesing]])"}, {"kategorie": "", "text": "Vermutlich von einem Architekten aus dem Umfeld des bedeutenden Barockbaumeisters Johann Bernhard Fischer von Erlach entworfen, spiegelt das Schlössl die charakteristische Architektur dieser Zeit wider, die sich durch repräsentative Bauformen und kunstvoll angelegte Gärten auszeichnete"}, {"kategorie": "", "text": "Die Gartenanlagen um das Schloss waren ein wesentlicher Bestandteil des Gesamtkonzepts barocker Residenzen, die nicht nur als Wohnsitze dienten, sondern auch repräsentative Treffpunkte für gesellschaftliche Anlässe und Orte der Erholung waren. Das Maria-Theresien-Schlössl fügte sich mit seiner weitläufigen Parkanlage nahtlos in diese Tradition ein und bot seinen Bewohnern einen Rückzugsort im Grünen, fernab vom hektischen Stadtleben"}, {"kategorie": "", "text": "In den letzten Jahrzehnten wurde das Maria-Theresien-Schlössl einer vorbildhaften Restaurierung unterzogen, um seinen historischen Charakter zu bewahren und gleichzeitig moderne Anforderungen zu erfüllen. Die Restaurierung erfolgte unter Berücksichtigung der denkmalpflegerischen Auflagen, da das Schlössl als denkmalgeschütztes Gebäude (Objekt-ID 21674) eingestuft ist. Dabei wurde besonderer Wert auf die Erhaltung der originalen Bausubstanz gelegt, insbesondere bei den barocken Elementen wie Fassaden, Stuckarbeiten und den kunstvollen Innenräumen."}]'::jsonb, ''),
  ('wueda-beag', 'Wüda Beag', '', '', '', '', 'Wilder Berg', '[{"kategorie": "allg.", "text": "\"370 Meter hoher Berg im 23. Wiener Gemeindebezirk ([[Liesing]]) und der höchste Berg im Bezirksteil [[Mauer]]\""}, {"kategorie": "", "text": "Er ist der dritthöchste Berg im gesamten Bezirk Liesing, wobei nur der [[Eichkogel]] (428 m) in [[Rodaun]] und ein namenloser Hügel (377 m) in [[Kalksburg]] höher sind"}, {"kategorie": "", "text": "Der Wilde Berg liegt im [[Maurer]] Wald, einem Teil des [[Wienerwalds]], und befindet sich zwischen dem [[Faßlberg]] im Westen und der [[Antonshöhe]] im Süden"}, {"kategorie": "", "text": "Der Wilde Berg hat auch historische Bedeutung: 1834 wurde im Nordwesten ein Schießplatz für die Kasernen in Mauer errichtet"}, {"kategorie": "", "text": "Im Jahr 1865 entstand ein Zivil-Schießplatz samt Restauration südlich des Gipfels"}, {"kategorie": "", "text": "Nach dem [[Ersten]] Weltkrieg wurde der Militär-Schießplatz aufgegeben, und das Gelände wurde zunächst als Erholungsheim für Frauen und Kinder genutzt"}, {"kategorie": "", "text": "[[Im]] Zweiten Weltkrieg wurde ein neuer Schießplatz für die Luftnachrichtentruppen-Kaserne errichtet, dessen Ruinen um das Jahr 2000 entfernt wurden."}]'::jsonb, ''),
  ('klaana-eichbeag', 'Klaana Eichbeag', '', '', '', '', 'Kleiner Eichberg', '[{"kategorie": "allg.", "text": "\"334 Meter hoher Berg im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Er liegt im südwestlichen Teil des Bezirks in der Katastralgemeinde [[Auhof]], an der Grenze zum 23. Bezirk ([[Liesing]]) und zur niederösterreichischen Gemeinde Breitenfurt"}, {"kategorie": "", "text": "Der Kleine Eichberg ist Teil des [[Lainzer]] Tiergartens und des Wienerwaldes, der den nordöstlichen Ausläufer der Ostalpen bildet"}, {"kategorie": "", "text": "In seiner Umgebung befinden sich der [[Kaiserzipf]] im Westen, der [[Mittlere]] Eichberg im Norden und der [[Faßlberg]] im Südosten"}, {"kategorie": "", "text": "Der bewaldete Hügel, genannt [[Mackwald]], wird von zwei Bächen begrenzt: einem Quellbach des [[Gütenbachs]] im Norden, der den Berg im Süden begrenzt und über die Faßlbergwiese fließt, und dem [[Gütenbach]] selbst, der die südwestliche Grenze bildet"}, {"kategorie": "", "text": "Der Name \"Kleiner Eichberg\" leitet sich vermutlich von seinem Eichenbestand ab. Obwohl es auch einen [[Mittleren]] Eichberg und einen [[Vorderen]] Eichberg gibt, existiert im Lainzer Tiergarten kein „Großer Eichberg“"}, {"kategorie": "", "text": "Der Kleine Eichberg ist mit dem Mackwald bewachsen, der nach Franz von Mack, einem ehemaligen Besitzer der Herrschaften [[Kalksburg]] und [[Mauer]], benannt ist"}, {"kategorie": "", "text": "Die umliegende Große Stockwiese, erstmals 1819 urkundlich erwähnt, könnte ihren Namen von Baumstümpfen haben, die nach Rodungen in der Wiese zurückblieben."}]'::jsonb, ''),
  ('mittlara-eichbeag', 'Mittlara Eichbeag', '', '', '', '', 'Mittlerer Eichberg', '[{"kategorie": "allg.", "text": "372 Meter hoher Berg im 13. Wiener Gemeindebezirk ([[Hietzing]]) und Teil des [[Lainzer]] Tiergartens (auch [[Vorderer Eichberg]] geannt)"}, {"kategorie": "", "text": "Der Mittlere Eichberg liegt im südwestlichen Teil von Hietzing und gehört zum [[Wienerwald]], dem nordöstlichsten Ausläufer der Ostalpen"}, {"kategorie": "", "text": "In seiner Umgebung befinden sich: der [[Kaltbründlberg]] im Norden, der [[Kaiserzipf]] im Südwesten und der [[Kleine]] Eichberg im Süden"}, {"kategorie": "", "text": "Der Hügel ist größtenteils bewaldet, und am südwestlichen Abhang entspringt ein Quellbach des [[Gütenbachs]], während ein weiterer Quellbach östlich des Berges verläuft. Nördlich des Berges liegt die Kleefrischewiese"}, {"kategorie": "", "text": "Der Name Mittlerer Eichberg geht vermutlich auf den Eichenbestand des Berges zurück. Der Berg wurde erstmals 1819 urkundlich erwähnt. Obwohl es einen [[Vorderen]] Eichberg (die südwestliche Schulter des Mittleren Eichbergs) und einen [[Kleinen]] Eichberg gibt, existiert im [[Lainzer]] Tiergarten kein „Großer“ oder „Hinterer“ Eichberg."}]'::jsonb, ''),
  ('vuadara-eichbeag', 'Vuadara Eichbeag', '', '', '', '', 'Vorderer Eichberg', '[{"kategorie": "allg.", "text": "372 Meter hoher Berg im 13. Wiener Gemeindebezirk ([[Hietzing]]) und Teil des [[Lainzer]] Tiergartens (auch [[Mittlerer Eichberg]] geannt)"}, {"kategorie": "", "text": "Der Vordere Eichberg liegt im südwestlichen Teil von Hietzing und gehört zum [[Wienerwald]], dem nordöstlichsten Ausläufer der Ostalpen"}, {"kategorie": "", "text": "In seiner Umgebung befinden sich: der [[Kaltbründlberg]] im Norden, der [[Kaiserzipf]] im Südwesten und der [[Kleine]] Eichberg im Süden"}, {"kategorie": "", "text": "Der Hügel ist größtenteils bewaldet, und am südwestlichen Abhang entspringt ein Quellbach des [[Gütenbachs]], während ein weiterer Quellbach östlich des Berges verläuft. Nördlich des Berges liegt die Kleefrischewiese"}, {"kategorie": "", "text": "Der Name \"Vorderer Eichberg\" geht vermutlich auf den Eichenbestand des Berges zurück. Der Berg wurde erstmals 1819 urkundlich erwähnt. Obwohl es einen Vorderen Eichberg (die südwestliche Schulter des [[Mittleren]] Eichbergs) und einen [[Kleinen]] Eichberg gibt, existiert im [[Lainzer]] Tiergarten kein „Großer“ oder „Hinterer“ Eichberg."}]'::jsonb, ''),
  ('johannsa-kogl', 'Johannsa Kogl', '', '', '', '', 'Johannser Kogel', '[{"kategorie": "allg.", "text": "\"377 Meter hoher Hügel am gebirgigen Westrand des 13. Wiener Gemeindebezirks ([[Hietzing]]), der etwa 200 Meter über das [[Wiental]] aufragt\""}, {"kategorie": "", "text": "Der Johannser Kogel befindet sich im westlichen Teil von Hietzing im Naturschutzgebiet des [[Lainzer]] Tiergartens. Im Südwesten liegt der [[Brandberg]], und im Osten erhebt sich der etwas höhere [[Hagenberg]]"}, {"kategorie": "", "text": "Der vollständig bewaldete Hügel gehört zum [[Wienerwaldgebirge]], das den nordöstlichen Ausläufer der Ostalpen bildet, und liegt im [[Johannser]] Wald"}, {"kategorie": "", "text": "Im Westen und Norden wird der Johannser Kogel vom [[Rotwasser]] umflossen, während am westlichen Abhang Teile des Quellgebiets des [[Grünauer]] Bachs liegen, der ebenfalls in die Wien mündet"}, {"kategorie": "", "text": "Der Name Johannser Kogel wurde erstmals 1925 urkundlich erwähnt und leitet sich vom Johannser Wald ab, in dem der Hügel liegt. Der Johannser Wald wurde bereits 1687 als \"St. Johann(s) Waldt\" urkundlich erwähnt und geht auf den ehemaligen Besitzer, den Johanniterorden (auch Malteserorden genannt), zurück. Weitere geografische Bezeichnungen wie der Johannser Schütt (Schwemmgebiet des [[Grünauer]] Bachs), der Johannser Rennweg (ein Weg durch das Gebiet) und die Johannser Wiese südlich des Hügels stammen ebenfalls von diesen Besitzern"}, {"kategorie": "", "text": "Der Johannser Kogel wurde 1972 zum Naturwaldreservat erklärt und der natürlichen Entwicklung überlassen. Von den 70 Hektar des Reservats sind 45 Hektar umzäunt und für Besucher des [[Lainzer]] Tiergartens nicht zugänglich. In diesem Gebiet gibt es rund 400 Jahre alte Eichen mit Stammumfängen von mehr als vier Metern."}]'::jsonb, ''),
  ('siivaringa-boch', 'Siivaringa Boch', '', '', '', '', 'Sieveringer Bach', '[{"kategorie": "allg.", "text": "\"Bach im 19. Wiener Gemeindebezirk ([[Döbling]]), der teilweise offen und teilweise als Bachkanal geführt wird (auch \"Erbsenbach\" oder \"Arbesbach\" genannt)\""}, {"kategorie": "", "text": "Der etwa 4,3 Kilometer lange Bach ist der wichtigste Nebenfluss des [[Krottenbachs]] und verläuft größtenteils im Bezirksteil [[Sievering]]"}, {"kategorie": "", "text": "Der Sieveringer Bach entspringt im Wienerwald zwischen dem [[Dreimarkstein]] und dem Latisberg ([[Cobenzl]]) und fließt entlang der [[Sieveringer]] Straße. Mehrere Quellarme, wie der Gereutebach, vereinigen sich zum Sieveringer Bach, der schließlich in den [[Krottenbach]] mündet"}, {"kategorie": "", "text": "Im Mittel- und Unterlauf ist der Bach teilweise überbaut oder verrohrt, besonders im dicht besiedelten Gebiet von [[Sievering]], wo er zunehmend in den Bachkanal übergeht"}, {"kategorie": "", "text": "Früher war der Sieveringer Bach ein oft unkontrollierbarer Gebirgsbach, der regelmäßig Überschwemmungen verursachte und zur Abfallentsorgung genutzt wurde. Zwischen 1894 und 1896 begann die Einwölbung des Baches, um die Überschwemmungen und Geruchsbelästigungen zu reduzieren"}, {"kategorie": "", "text": "In den 1950er und 1960er Jahren wurde diese Einwölbung im Ortskern von Sievering weitergeführt."}]'::jsonb, ''),
  ('gruenaua-boch', 'Grünaua Boch', '', '', '', '', 'Grünauer Bach', '[{"kategorie": "allg.", "text": "\"Bach im 13. Wiener Gemeindebezirk ([[Hietzing]]) und ein Zubringer des [[Wienflusses]]\""}, {"kategorie": "", "text": "Der Grünauer Bach hat eine Länge von 3250 Metern, entspringt in der Nähe des Rasthauses Rohrhaus und fließt in nördlicher Richtung durch den [[Lainzer]] Tiergarten. Er durchquert den [[Grünauer]] Teich und nimmt hinter dem Teich rechtsseitig den [[Schallautzergraben]] auf"}, {"kategorie": "", "text": "Außerhalb des Lainzer Tiergartens unterquert er die [[Wientalstraße]] und mündet im [[Rückhaltebecken]] Auhof in [[Hütteldorf]] in den [[Wienfluss]]"}, {"kategorie": "", "text": "Der Grünauer Bach ist ökologisch wertvoll und dient als Laichgewässer für verschiedene Amphibienarten wird von mehreren Brücken überquert, darunter: (i) Wegschüttbrücke (erbaut 1940) und (ii) Grünauer Brücke (erbaut 1969)"}, {"kategorie": "", "text": "Der Grünauer Bach ist somit ein naturnaher Waldbach, der eine wichtige Rolle im Ökosystem des Lainzer Tiergartens spielt und als wertvolles Habitat für Amphibien und andere Tiere dient."}]'::jsonb, ''),
  ('gruenaua-teich', 'Grünaua Teich', '', '', '', '', 'Grünauer Teich', '[{"kategorie": "allg.", "text": "\"künstlich angelegtes Gewässer mit einer Fläche von 7.785 m² im Naturschutzgebiet [[Lainzer]] Tiergarten, im 13. Wiener Gemeindebezirk ([[Hietzing]]), gelegen zwischen dem Pulverstampftor und dem Nikolaitor\""}, {"kategorie": "", "text": "Der Teich wurde im 18. Jahrhundert angelegt, um den Wasserbedarf des Wildes im Lainzer Tiergarten auch in den Sommermonaten zu decken. Dazu wurde der Grünauer Bach aufgestaut"}, {"kategorie": "", "text": "Aufgrund des porösen Untergrunds waren kontinuierlich Reparaturen und Abdichtungsarbeiten erforderlich. Nach mehreren Damm- und Uferabbrüchen, insbesondere nach der Zerstörung des Wehrs durch Eisdruck im Jahr 1809, wurde der Teich trotzdem weiter genutzt"}, {"kategorie": "", "text": "Im Jahr 1835 wurden die Ufer mit Pflastersteinen befestigt, und die Kosten der Befestigung konnten teilweise durch den Verkauf von Wintereis gedeckt werden"}, {"kategorie": "", "text": "Zwischen den Weltkriegen wurde der Teich zeitweise zum Baden und Kahnfahren freigegeben, allerdings ohne großen Erfolg. Versuche, den Teich zur Krebs- und Karpfenzucht zu nutzen, waren ebenfalls nur bedingt erfolgreich. Nach der kommerziellen Nutzung entwickelte sich der Teich naturnah. 1990 wurde er ausgebaggert, um den verschlammten Boden zu reinigen"}, {"kategorie": "", "text": "Der Teich ist eutroph (hoher Phosphatgehalt) und weist Badewasserqualität auf, jedoch ist das Baden aus Gründen des Naturschutzes verboten."}]'::jsonb, ''),
  ('oba-sankt-veita-schloss', 'Oba-Sankt-Veita Schloss', '', '', '', '', 'Ober-Sankt-Veiter Schloss', '[{"kategorie": "", "text": "Kaiserin [[Maria]] Theresia kaufte das Schloss Ober-Sankt-Veit 1762 für die stolze Summe von 65.000 Goldgulden und nutzte sie das Schloss bis 1779 als Zweitwohnsitz. Um leichter zwischen ihren beiden Residenzen ([[Schloss]] Schönbrunn und Ober-Sankt-Veiter Schloss) zu reisen, ließ die Kaiserin die heutige [[Hietzinger]] Hauptstraße anlegen, die einst direkt vor dem Ehrenhof von Schönbrunn endete"}, {"kategorie": "", "text": "Im Jahre 1779 erfolgte der Rückkauf des Schlosses durch das Erzbistum Wien und wurde fortan als Sommerresidenz der Erzbischöfe genutzt"}, {"kategorie": "", "text": "Noch im Auftrag von Maria Theresia hatte Johann Baptist Wenzel Bergl (ein österreichischer Maler des Rokoko) sechs Zimmer im Ober-Sankt-Veiter Schloss künstlerisch gestaltet, von denen vier noch erhalten sind. Die Wände dieser Räume sind mit exotischen, vorwiegend südamerikanischen Motiven geschmückt, die zur damaligen Zeit die Wahrnehmung ferner Länder widerspiegelten"}, {"kategorie": "", "text": "Die Barockgalerie, einer der bedeutendsten Räume des Schlosses, ist mit Malereien geschmückt, die den Frühling, Sommer und Herbst darstellen. Später wurde ein weiterer Raum hinzugefügt, der eine allegorische Verherrlichung des Erzhauses Habsburg zeigt. Charakteristisch sind die Darstellungen gefangener Türkenfiguren, die symbolisch die Last der Architektur tragen"}, {"kategorie": "", "text": "Während der napoleonischen Kriege wurde das Schloss als Militärspital genutzt (1809). Von 1822 bis 1831 ließ Erzbischof Leopold Maximilian Firmian"}, {"kategorie": "", "text": "Das Schloss beherbergt heute zwei Privatschulen mit Öffentlichkeitsrecht, die sich auf die Ausbildung im pastoralen Dienst und in der Jugendarbeit spezialisiert haben. Es ist nach wie vor ein Ort, an dem kirchliche Aktivitäten und Ausbildungen im Vordergrund stehen. Die beeindruckenden barocken und biedermeierlichen Kunstwerke, die das Schloss zieren, machen es zu einem kulturell bedeutenden Ort in Wien."}]'::jsonb, ''),
  ('schalautzer-groom', 'Schalautzer Groom', '', '', '', '', 'Schallautzergraben', '[{"kategorie": "", "text": "Der Schallautzergraben hat eine Länge von 1275 Metern, verläuft durch das Naturschutzgebiet [[Lainzer]] Tiergarten und entspringt südlich des [[Hagenbergs]], nahe dem [[Veitlissengraben]]. Von dort fließt er in nordwestlicher Richtung"}, {"kategorie": "", "text": "Der Bach unterquert die Schallautzerbrücke (erbaut 1940), eine 7 Meter lange und 4 Meter breite Steinbrücke bei der [[Stegtorstraße]], und mündet rechtsseitig unterhalb des [[Grünauer]] Teichs in den [[Grünauer]] Bach"}, {"kategorie": "", "text": "Der Name Schallautzergraben geht auf Hermes Schallautzer (1503–1561) zurück, einen Wiener Bürgermeister und Festungsbaumeister, der in diesem Gebiet Besitzungen hatte"}, {"kategorie": "", "text": "Der Schallautzergraben ist ein naturnaher Bach, der Teil des ökologisch wertvollen Lainzer Tiergartens ist und eine bedeutende Rolle im Wassersystem des [[Wienerwaldes]] spielt."}]'::jsonb, ''),
  ('hackinga-kej', 'Hackinga Kej', '', '', '', '', 'Hackinger Kai', '[{"kategorie": "allg.", "text": "\"Uferstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), die entlang des rechten Ufers des [[Wienflusses]] verläuft\""}, {"kategorie": "", "text": "Der Kai befindet sich zwischen dem [[Hackinger]] Steg und der [[Zufferbrücke]] und wurde am 28. März 1906 nach seiner Lage im Stadtteil [[Hacking]] benannt"}, {"kategorie": "", "text": "Hacking ist ein historischer Vorort von Wien und heute ein Teil des Bezirks Hietzing sowie eine von 89 Katastralgemeinden der Stadt Wien. Hacking liegt am westlichen Stadtrand von Wien und grenzt an den Wienfluss, der durch das [[Wiental]] fließt"}, {"kategorie": "", "text": "Der Hackinger Kai entstand im Rahmen der [[Wienflussregulierung]], die Ende des 19. und Anfang des 20. Jahrhunderts stattfand. Diese Maßnahme war Teil eines größeren städtischen Projekts zur Eindämmung und Kontrolle des Wienflusses, um Hochwasserschutz und den Ausbau der Verkehrsinfrastruktur zu gewährleisten"}, {"kategorie": "", "text": "Entlang des Wienflusses wurden verschiedene Kais und Brücken errichtet, um die Verkehrswege zwischen den angrenzenden Stadtteilen zu verbessern"}, {"kategorie": "", "text": "Heute dient der Hackinger Kai als Verkehrsverbindung entlang des westlichen Stadtrands von Wien und ermöglicht eine rasche Durchfahrt Richtung Stadtzentrum."}]'::jsonb, ''),
  ('obabaumgoatna-kiachn', 'Obabaumgoatna Kiachn', '', '', '', '', 'Oberbaumgartner Kirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 14. Wiener Gemeindebezirk ([[Penzing]]) am Baumgartner Spitz, auch bekannt als die \"Kirche Zu den vier heiligen Evangelisten\""}, {"kategorie": "", "text": "Sie wurde zwischen 1963 und 1965 nach den Plänen des Architekten Johann Georg Gsteu im Stil des [[Brutalismus]] errichtet"}, {"kategorie": "", "text": "Die Grundsteinlegung der neuen Kirche erfolgte im Jahr 1963, und am 19. Dezember 1965 wurde die Kirche geweiht. Seit 2019 ist die ehemals eigenständige Pfarre Teil der größeren Pfarre Heilige Mutter Teresa ([[Pfarrkirche]] Oberbaumgarten) und fungiert seither als Filialkirche"}, {"kategorie": "", "text": "Der Kirchenbau zeichnet sich durch seine strenge, modulare Gestaltung aus, die auf dem Quadrat und Würfel basiert. Die Idee zur besonderen Konstruktion des Gebäudes kam dem Architekten Johann Georg Gsteu bei einer Reise nach Rom, inspiriert vom Pantheon"}, {"kategorie": "", "text": "Der Altar, im Zentrum des quadratisch angelegten Baus, befindet sich auf einem zweistufigen Podest. Eine besondere Innovation war das Taufbecken und der Tabernakel, die aus transparentem Polyester gegossen wurden, was in der damaligen Zeit eine unkonventionelle und kritisierte Lösung war"}, {"kategorie": "", "text": "Von 1989 bis 1992 wurde eine umfangreiche Sanierung der Kirche und der Nebengebäude durchgeführt. Heute ist die Oberbaumgartner Kirche nach § 2a des österreichischen Denkmalschutzgesetzes als Denkmal geschützt und gilt als ein bedeutendes Beispiel des modernen Kirchenbaus in Österreich."}]'::jsonb, ''),
  ('pfoakiachn-baumgoatn', 'Pfoakiachn Baumgoatn', '', '', '', '', 'Pfarrkirche Baumgarten', '[{"kategorie": "", "text": "Sie ist der heiligen Anna geweiht und befindet sich am [[Gruschaplatz]] an der Linzer Straße. Die Kirche hat eine lange Geschichte und wurde im Laufe der Jahrhunderte mehrmals zerstört und wieder aufgebaut. Der heutige Bau stammt aus den Jahren 1906 bis 1908 und vereint architektonische Elemente der [[Neuromanik]] und des [[Heimatstils]]"}, {"kategorie": "", "text": "Die heutige Pfarrkirche wurde nach den Plänen des Architekten Moritz Otto Kuntschik errichtet. Die Grundsteinlegung erfolgte 1906, und die Einweihung fand am 24. November 1908 statt"}, {"kategorie": "", "text": "Das Kirchengebäude ist ein beeindruckendes Beispiel der [[Neuromanik]] und des [[Heimatstils]]. Es besitzt zwei eng beieinander stehende, achteckige Zwillingstürme an der Nordfassade. Der Eingang wird von einem [[Portikus]] in Form eines Triumphbogens dominiert. An das Langhaus schließt im Süden ein niedriger Chor an"}, {"kategorie": "", "text": "Im Inneren befindet sich ein gotisches Sandsteinrelief „Heilige Anna Selbdritt“, das auf das Jahr 1511 datiert ist und ursprünglich Teil der alten Kirche war. In der Apsis sind die heilige Anna sowie weitere Heilige und der Architekt des Kirchenbaus dargestellt"}, {"kategorie": "", "text": "Die meisten Einrichtungsgegenstände der Kirche stammen aus der Bauzeit, einschließlich eines Kruzifixes des Südtiroler Bildhauers Ferdinand Stuflesser. Besonders hervorzuheben ist die Marienkapelle, die eine Kopie des berühmten Gnadenbilds Mariahilf beherbergt, sowie ein spätgotisches [[Epitaph]] im rechten Seitenschiff."}]'::jsonb, '')
